-- Core current definition. Domain definitions are listed explicitly in current.py.

CREATE TABLE schema_migrations (version INTEGER PRIMARY KEY, name TEXT NOT NULL, applied_at REAL NOT NULL);
CREATE TABLE identities (
  id INTEGER PRIMARY KEY,
  label TEXT NOT NULL,
  credential_ref TEXT NOT NULL,
  brand_account_id TEXT,
  is_master INTEGER NOT NULL DEFAULT 0 CHECK(typeof(is_master)='integer' AND is_master IN (0,1)),
  last_auth_ok REAL,
  active INTEGER NOT NULL DEFAULT 1 CHECK(typeof(active)='integer' AND active IN (0,1)),
  UNIQUE(label)
);
CREATE TABLE playlists (
  id INTEGER PRIMARY KEY,
  identity_id INTEGER NOT NULL REFERENCES identities(id),
  ytm_playlist_id TEXT NOT NULL,
  title TEXT, track_count INTEGER,
  content_hash TEXT,
  first_seen REAL, last_seen REAL, last_changed REAL,
  created_at REAL,                        -- actual creation time; NULL when unknown, never a sync date
  created_at_source TEXT,                 -- local creation or authoritative youtube metadata
  thumbnail TEXT, scope_ref TEXT REFERENCES playlist_scopes(ref),
  UNIQUE(identity_id, ytm_playlist_id)
);
CREATE TABLE play_events (
  id INTEGER PRIMARY KEY,
  identity_id INTEGER NOT NULL REFERENCES identities(id),
  identity_key TEXT NOT NULL,              -- #75 live now-playing stream: one row per real play,
  video_id TEXT,                           -- real timestamps (the (track,day) history model stays
  played_at REAL NOT NULL,                 -- the coarse view every existing consumer reads)
  playlist_ytm_id TEXT,                    -- provenance: the list= id when played from a playlist
  like_status TEXT,                        -- LIKE | DISLIKE | INDIFFERENT at report time
  source TEXT NOT NULL DEFAULT ''
, recording_id INTEGER REFERENCES recordings(id), raw_identity_key TEXT, is_generated INTEGER CHECK(is_generated IN (0,1)));
CREATE TABLE player_events (
  id INTEGER PRIMARY KEY,
  identity_id INTEGER NOT NULL REFERENCES identities(id),
  kind TEXT NOT NULL,                      -- #91 raw sensor stream: track_exit | ended | state |
  video_id TEXT,                           -- tick | volume | bye | rate | playlist_edit |
  position REAL,                           -- feedback | subscription | share_intent
  duration REAL,
  playlist_ytm_id TEXT,
  payload TEXT,                            -- JSON extras per kind (state/volume/shuffle/repeat or url/body/href/action)
  at REAL NOT NULL
);
CREATE TABLE actions (
  id INTEGER PRIMARY KEY,
  kind TEXT NOT NULL,
  params_json TEXT, plan_json TEXT, undo_json TEXT,
  status TEXT NOT NULL,
  created_at REAL, executed_at REAL
);
CREATE TABLE settings (
  key TEXT PRIMARY KEY NOT NULL, value TEXT   -- small app settings, e.g. lastfm_api_key
);
CREATE TABLE genre_family (
  key TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL
);
CREATE TABLE genre_catalog (
  key TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL,
  family_key TEXT REFERENCES genre_family(key),
  source TEXT NOT NULL, family_source TEXT, description TEXT NOT NULL DEFAULT ''
);
CREATE TABLE genre_alias (
  label_key TEXT PRIMARY KEY NOT NULL, label TEXT NOT NULL,
  genre_key TEXT NOT NULL REFERENCES genre_catalog(key), source TEXT NOT NULL
);
CREATE TABLE genre_external_id (
  provider TEXT NOT NULL, external_id TEXT NOT NULL,
  genre_key TEXT NOT NULL REFERENCES genre_catalog(key),
  PRIMARY KEY (provider, external_id)
);
CREATE TABLE rec_model_selection_runs (
  id INTEGER PRIMARY KEY,
  started_at REAL NOT NULL,
  result_json TEXT NOT NULL
, identity_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE rec_model_previous_vectors (
  run_id INTEGER NOT NULL REFERENCES rec_model_selection_runs(id),
  identity_key TEXT NOT NULL,
  vec BLOB NOT NULL,
  PRIMARY KEY (run_id, identity_key)
);
CREATE TABLE rec_model_forecasts (
  run_id INTEGER NOT NULL REFERENCES rec_model_selection_runs(id),
  made_at REAL NOT NULL,
  forecast_json TEXT NOT NULL,
  PRIMARY KEY (run_id, made_at)
);
CREATE TABLE rec_feedback (
  surface TEXT NOT NULL,                  -- where it happened: 'for_you', 'suggest', 'discover'
  item_key TEXT NOT NULL,                 -- track identity_key (or 'artist:<name>' for a mute)
  kind TEXT NOT NULL,                     -- 'dismiss' | 'less' | 'more' | 'mute' | 'not_now'
  reason TEXT,                            -- optional axis/reason ('era','artist','vibe','own_it')
  scope TEXT NOT NULL DEFAULT '',         -- '' = global; else a playlist id for playlist-local
  until REAL,                             -- suppressed until ts (NULL = until explicitly cleared)
  created_at REAL, target_type TEXT NOT NULL DEFAULT 'legacy_unresolved', recording_id INTEGER REFERENCES recordings(id), artist_id INTEGER REFERENCES artists(id),
  PRIMARY KEY (surface, item_key, scope)
);
CREATE TABLE rec_weights (
  axis TEXT PRIMARY KEY NOT NULL,                  -- e.g. 'lane:deep_cut', 'family:techno'
  weight REAL NOT NULL DEFAULT 1.0,       -- learned blend weight; 1.0 = prior
  updated_at REAL                         -- #85 last nudge time; drives time-proportional reversion at read
);
CREATE TABLE rec_lean (
  axis TEXT PRIMARY KEY NOT NULL,                  -- 'genre:<fam>' | 'genre:<sub>' | 'era:<decade>' | 'artist:<name>'
  value REAL NOT NULL DEFAULT 1.0,        -- standing transient multiplier; 1.0 = neutral (non-decaying)
  updated_at REAL,                        -- when the slider was last moved (drives held-day exposure)
  last_graduated_day TEXT                 -- UTC date (YYYY-MM-DD) of last exposure-graduation, or NULL
);
CREATE TABLE home_hidden_facet (
  axis TEXT PRIMARY KEY NOT NULL                   -- 'genre:<name>' | 'era:<decade>' hidden from the Home panel
);
CREATE TABLE wiki_cards (
  subject    TEXT PRIMARY KEY NOT NULL,
  kind       TEXT NOT NULL,
  display    TEXT NOT NULL,
  title      TEXT,
  extract    TEXT,
  thumbnail  TEXT,
  url        TEXT,
  found      INTEGER NOT NULL,
  fetched_at REAL NOT NULL
);
CREATE TABLE taste_modes (
  mode_id     INTEGER PRIMARY KEY,
  label       TEXT NOT NULL,
  families    TEXT NOT NULL,
  centroid    BLOB NOT NULL,
  size        INTEGER NOT NULL,
  rep_keys    TEXT NOT NULL,
  active      INTEGER NOT NULL,
  first_seen  REAL NOT NULL,
  last_seen   REAL NOT NULL,
  -- Fingerprint of the content space `centroid` lives in (embed.content_model_fingerprint). A
  -- centroid is only comparable to one from the same space; '' means "built before we tracked
  -- this", which never matches and so retires cleanly on the next recompute.
  space       TEXT NOT NULL DEFAULT ''
);
CREATE TABLE rec_lane_impressions (
  id INTEGER PRIMARY KEY,
  lane TEXT NOT NULL,                      -- #87 which home lane served the item
  identity_key TEXT NOT NULL,              -- what was shown (future lane-bandit success join)
  at REAL NOT NULL
, recording_id INTEGER REFERENCES recordings(id), raw_identity_key TEXT);
CREATE TABLE trend_first_play (
  kind      TEXT NOT NULL,        -- 'track' (identity_key) | 'artist' (display name)
  id_key    TEXT NOT NULL,
  first_day INTEGER NOT NULL,     -- int(first_ts // 86400)
  first_ts  REAL NOT NULL,
  source    TEXT NOT NULL,        -- 'history' | 'play_event'
  PRIMARY KEY (kind, id_key)
);
CREATE TABLE artist_scans (
  artist TEXT PRIMARY KEY NOT NULL,
  scanned_at REAL                         -- last time we hit YT/Last.fm for this artist
, artist_id INTEGER REFERENCES artists(id));
CREATE TABLE discovered_artists (
  artist TEXT PRIMARY KEY NOT NULL,
  score REAL, because TEXT, fits TEXT, thumbnail TEXT,
  found_at REAL, last_shown REAL,
  genre TEXT                              -- #18: candidate genre for the facet overlay
, first_shown REAL, offered_count INTEGER NOT NULL DEFAULT 0, legacy_offered_count INTEGER NOT NULL DEFAULT 0, legacy_first_shown REAL, legacy_last_shown REAL, artist_id INTEGER REFERENCES artists(id));
CREATE TABLE discovery_visible_impressions (
  view_id TEXT NOT NULL, kind TEXT NOT NULL, item_id TEXT NOT NULL, shown_at REAL NOT NULL,
  PRIMARY KEY (view_id, kind, item_id)
);
CREATE TABLE rec_impressions (
  surface TEXT NOT NULL,                  -- 'for_you' | 'explore' | 'suggest'
  item_key TEXT NOT NULL,
  views INTEGER NOT NULL DEFAULT 0,       -- times shown (debounced), for anti-staleness erosion
  last_shown REAL,                        -- drives the recycle cooldown
  PRIMARY KEY (surface, item_key)
);
CREATE TABLE rec_proposals (
  surface TEXT PRIMARY KEY NOT NULL,               -- 'fresh_songs' | 'discover'
  payload TEXT NOT NULL,                  -- JSON, materialized by the rec worker (last-good serving)
  built_at REAL
);
CREATE TABLE rec_artist_similar (
  artist TEXT PRIMARY KEY NOT NULL,                -- anchor artist (display name)
  payload TEXT NOT NULL,                  -- JSON [[name, match], ...] from Last.fm
  fetched_at REAL
, artist_id INTEGER REFERENCES artists(id));
CREATE TABLE rec_theme (
  facet      TEXT PRIMARY KEY NOT NULL,             -- 'genre:<fam>' | 'era:<decade>' | 'artist:<name>'
  score      REAL NOT NULL,                -- persistent signed running total (interaction-driven, no time decay)
  updated_at REAL NOT NULL                 -- bookkeeping only
);
CREATE TABLE rec_play_grad (
  axis               TEXT PRIMARY KEY NOT NULL,      -- facet token, e.g. 'genre:techno'
  last_graduated_day TEXT                   -- UTC YYYY-MM-DD the play-exposure funnel last graduated this axis
);
CREATE TABLE rec_grad_log (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  axis       TEXT NOT NULL,                 -- the facet that graduated, e.g. 'genre:techno'
  source     TEXT NOT NULL,                 -- the signal that drove it: 'play' | 'slider' | 'vibe' | 'like' | ...
  score      REAL NOT NULL,                 -- the ledger value at the crossing (what tripped THEME_THRESHOLD)
  factor     REAL NOT NULL,                 -- the nudge multiplier applied (graduate_up / graduate_down)
  new_weight REAL NOT NULL,                 -- the resulting permanent weight after the nudge
  created_at REAL NOT NULL
);
CREATE TABLE rec_served_impressions (
  id                INTEGER PRIMARY KEY,
  request_id        TEXT NOT NULL,
  surface           TEXT NOT NULL,
  lane              TEXT NOT NULL,
  mode_id           INTEGER,
  identity_key      TEXT NOT NULL,
  rank               INTEGER NOT NULL,
  score              REAL,
  model_version      TEXT NOT NULL,
  provenance         TEXT NOT NULL,
  served_at          REAL NOT NULL, recording_id INTEGER REFERENCES recordings(id), raw_identity_key TEXT,
  UNIQUE(request_id, surface, rank)
);
CREATE TABLE road_trip_recipes (
  id               INTEGER PRIMARY KEY AUTOINCREMENT,
  name             TEXT NOT NULL,
  own_pct          INTEGER NOT NULL CHECK(typeof(own_pct)='integer' AND own_pct BETWEEN 0 AND 100),
  artists          TEXT NOT NULL,
  genres           TEXT NOT NULL,
  blacklist_genres TEXT NOT NULL,   -- legacy: the genre bars on the draft replaced it
  target_minutes   INTEGER NOT NULL CHECK(typeof(target_minutes)='integer' AND target_minutes BETWEEN 15 AND 720),
  last_playlist_id TEXT,
  created_at       REAL NOT NULL CHECK(typeof(created_at) IN ('integer','real') AND created_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308),
  updated_at       REAL NOT NULL CHECK(typeof(updated_at) IN ('integer','real') AND updated_at BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)
, familiarity_pct INTEGER NOT NULL DEFAULT 50 CHECK(typeof(familiarity_pct)='integer' AND familiarity_pct BETWEEN 0 AND 100));
CREATE INDEX ix_play_events_time ON play_events(played_at);
CREATE INDEX ix_play_events_key ON play_events(identity_key);
CREATE INDEX ix_player_events_at ON player_events(at);
CREATE INDEX ix_player_events_kind_at ON player_events(kind, at);
CREATE INDEX idx_genre_alias_genre ON genre_alias(genre_key);
CREATE INDEX ix_lane_impressions_at ON rec_lane_impressions(at);
CREATE INDEX ix_rec_served_at ON rec_served_impressions(served_at);
CREATE INDEX ix_rec_served_key_at ON rec_served_impressions(identity_key, served_at);
CREATE TABLE recordings (id INTEGER PRIMARY KEY AUTOINCREMENT,identity_key TEXT NOT NULL UNIQUE,title TEXT,artist TEXT,provisional INTEGER NOT NULL DEFAULT 1,genre TEXT,bpm REAL,energy REAL,danceability REAL,mb_recording_id TEXT,music_key TEXT,music_scale TEXT,mood_happy REAL,mood_sad REAL,mood_relaxed REAL,mood_acoustic REAL,instrumental REAL,created_at REAL,first_enriched_at REAL,last_enriched_at REAL);
CREATE TABLE youtube_items (video_id TEXT PRIMARY KEY NOT NULL CHECK(length(trim(video_id))>0),recording_id INTEGER NOT NULL REFERENCES recordings(id),title TEXT,artist TEXT,orig_title TEXT,orig_artist TEXT,album TEXT,duration_s INTEGER,available INTEGER,video_type TEXT,artist_browse_id TEXT,album_browse_id TEXT,thumbnail TEXT,mb_year TEXT,loudness REAL,dynamic_complexity REAL,popularity INTEGER,gain REAL,label TEXT,UNIQUE(video_id,recording_id));
CREATE INDEX ix_youtube_recording ON youtube_items(recording_id);
CREATE TABLE catalog_entries (id INTEGER PRIMARY KEY AUTOINCREMENT,recording_id INTEGER NOT NULL REFERENCES recordings(id),video_id TEXT UNIQUE REFERENCES youtube_items(video_id),source_ref TEXT UNIQUE,CHECK((video_id IS NOT NULL)<>(source_ref IS NOT NULL)),FOREIGN KEY(video_id,recording_id) REFERENCES youtube_items(video_id,recording_id) DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX ix_entries_recording ON catalog_entries(recording_id);
CREATE TABLE unresolved_items (entry_id INTEGER PRIMARY KEY REFERENCES catalog_entries(id),title TEXT,artist TEXT,orig_title TEXT,orig_artist TEXT,album TEXT,duration_s INTEGER,available INTEGER,video_type TEXT,artist_browse_id TEXT,album_browse_id TEXT,thumbnail TEXT,mb_year TEXT,loudness REAL,dynamic_complexity REAL,popularity INTEGER,gain REAL,label TEXT);
CREATE TABLE library_memberships (entry_id INTEGER PRIMARY KEY REFERENCES catalog_entries(id),origin TEXT NOT NULL,added_at REAL);
CREATE TABLE recording_aliases (alias TEXT NOT NULL,recording_id INTEGER NOT NULL REFERENCES recordings(id),source TEXT NOT NULL,PRIMARY KEY(alias,recording_id));
CREATE TABLE legacy_track_refs (legacy_id INTEGER PRIMARY KEY,entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),recording_id INTEGER NOT NULL REFERENCES recordings(id),video_id TEXT REFERENCES youtube_items(video_id));
CREATE TABLE recording_redirects (retired_id INTEGER PRIMARY KEY REFERENCES recordings(id),recording_id INTEGER NOT NULL REFERENCES recordings(id),source TEXT NOT NULL,evidence TEXT NOT NULL);
CREATE TABLE recording_identifiers (id INTEGER PRIMARY KEY,recording_id INTEGER NOT NULL REFERENCES recordings(id),scheme TEXT NOT NULL,entity_type TEXT NOT NULL,value TEXT NOT NULL,source TEXT NOT NULL,input_video_id TEXT REFERENCES youtube_items(video_id),status TEXT NOT NULL CHECK(status IN ('candidate','accepted','conflicting')),observed_at REAL);
CREATE INDEX ix_recording_identifier ON recording_identifiers(scheme,entity_type,value);
CREATE TABLE item_recording_associations (id INTEGER PRIMARY KEY,video_id TEXT NOT NULL REFERENCES youtube_items(video_id),recording_id INTEGER NOT NULL REFERENCES recordings(id),previous_recording_id INTEGER REFERENCES recordings(id),source TEXT NOT NULL,evidence TEXT NOT NULL,at REAL);
CREATE TABLE discovery_memberships (recording_id INTEGER PRIMARY KEY REFERENCES recordings(id),entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),found_at REAL,first_shown REAL,last_shown REAL,offered_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE discovery_sources (recording_id INTEGER NOT NULL REFERENCES recordings(id),source_token TEXT NOT NULL,input_video_id TEXT REFERENCES youtube_items(video_id),found_at REAL, source_type TEXT NOT NULL DEFAULT 'unknown', source_id TEXT, last_found_at REAL,PRIMARY KEY(recording_id,source_token));
CREATE TABLE playlist_items (playlist_id INTEGER NOT NULL REFERENCES playlists(id),video_id TEXT NOT NULL REFERENCES youtube_items(video_id),position INTEGER NOT NULL,PRIMARY KEY(playlist_id,video_id));
CREATE INDEX ix_playlist_item_video ON playlist_items(video_id);
CREATE TABLE unresolved_playlist_items (playlist_id INTEGER NOT NULL REFERENCES playlists(id),entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),position INTEGER NOT NULL,PRIMARY KEY(playlist_id,entry_id));
CREATE TABLE provider_attempts (id INTEGER PRIMARY KEY,recording_id INTEGER NOT NULL REFERENCES recordings(id),input_video_id TEXT NOT NULL DEFAULT '',provider TEXT NOT NULL,at REAL,status TEXT NOT NULL);
CREATE INDEX ix_provider_attempt_subject ON provider_attempts(recording_id,input_video_id,provider,at);
CREATE TABLE item_ratings (identity_id INTEGER NOT NULL REFERENCES identities(id),video_id TEXT NOT NULL,status TEXT NOT NULL,source TEXT NOT NULL,observed_at REAL NOT NULL,PRIMARY KEY(identity_id,video_id));
CREATE VIEW catalog_tracks AS SELECT e.id,e.recording_id,e.video_id,r.identity_key,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='title') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='title') ELSE COALESCE(y.title,u.title) END AS title,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='artist') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='artist') ELSE COALESCE(y.artist,u.artist) END AS artist,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='orig_title') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='orig_title') ELSE COALESCE(y.orig_title,u.orig_title) END AS orig_title,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='orig_artist') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='orig_artist') ELSE COALESCE(y.orig_artist,u.orig_artist) END AS orig_artist,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='album') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='album') ELSE COALESCE(y.album,u.album) END AS album,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='duration_s') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='duration_s') ELSE COALESCE(y.duration_s,u.duration_s) END AS duration_s,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='available') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='available') ELSE CASE WHEN e.video_id IS NULL THEN 0 ELSE COALESCE(y.available,u.available) END END AS available,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='video_type') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='video_type') ELSE COALESCE(y.video_type,u.video_type) END AS video_type,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='artist_browse_id') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='artist_browse_id') ELSE COALESCE(y.artist_browse_id,u.artist_browse_id) END AS artist_browse_id,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='album_browse_id') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='album_browse_id') ELSE COALESCE(y.album_browse_id,u.album_browse_id) END AS album_browse_id,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='thumbnail') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='thumbnail') ELSE COALESCE(y.thumbnail,u.thumbnail) END AS thumbnail,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mb_year') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mb_year') ELSE COALESCE(y.mb_year,u.mb_year) END AS mb_year,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='loudness') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='loudness') ELSE COALESCE(y.loudness,u.loudness) END AS loudness,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='dynamic_complexity') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='dynamic_complexity') ELSE COALESCE(y.dynamic_complexity,u.dynamic_complexity) END AS dynamic_complexity,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='popularity') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='popularity') ELSE COALESCE(y.popularity,u.popularity) END AS popularity,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='gain') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='gain') ELSE COALESCE(y.gain,u.gain) END AS gain,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='label') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='label') ELSE COALESCE(y.label,u.label) END AS label,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='genre') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='genre') ELSE r.genre END AS genre,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='bpm') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='bpm') ELSE r.bpm END AS bpm,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='energy') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='energy') ELSE r.energy END AS energy,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='danceability') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='danceability') ELSE r.danceability END AS danceability,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mb_recording_id') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mb_recording_id') ELSE r.mb_recording_id END AS mb_recording_id,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='music_key') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='music_key') ELSE r.music_key END AS music_key,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='music_scale') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='music_scale') ELSE r.music_scale END AS music_scale,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_happy') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_happy') ELSE r.mood_happy END AS mood_happy,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_sad') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_sad') ELSE r.mood_sad END AS mood_sad,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_relaxed') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_relaxed') ELSE r.mood_relaxed END AS mood_relaxed,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_acoustic') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='mood_acoustic') ELSE r.mood_acoustic END AS mood_acoustic,CASE WHEN EXISTS(SELECT 1 FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='instrumental') THEN (SELECT json_extract(ch.value_json,'$') FROM entry_field_choices ch WHERE ch.entry_id=e.id AND ch.field='instrumental') ELSE r.instrumental END AS instrumental,r.created_at,r.first_enriched_at,r.last_enriched_at FROM catalog_entries e JOIN recordings r ON r.id=e.recording_id LEFT JOIN youtube_items y ON y.video_id=e.video_id LEFT JOIN unresolved_items u ON u.entry_id=e.id;
CREATE VIEW tracks AS SELECT c.* FROM catalog_tracks c JOIN library_memberships m ON m.entry_id=c.id;
CREATE VIEW playable_library_tracks AS SELECT t.* FROM tracks t JOIN (SELECT e.recording_id,MIN(e.id) entry_id FROM catalog_entries e JOIN library_memberships m ON m.entry_id=e.id JOIN youtube_items y ON y.video_id=e.video_id WHERE COALESCE(y.available,1)<>0 GROUP BY e.recording_id) playable ON playable.entry_id=t.id;
CREATE VIEW playlist_tracks AS SELECT p.playlist_id,e.id track_id,p.position FROM playlist_items p JOIN catalog_entries e ON e.video_id=p.video_id UNION ALL SELECT playlist_id,entry_id,position FROM unresolved_playlist_items;
CREATE TRIGGER playlist_tracks_insert INSTEAD OF INSERT ON playlist_tracks BEGIN INSERT INTO playlist_items SELECT NEW.playlist_id,video_id,NEW.position FROM catalog_entries WHERE id=COALESCE((SELECT entry_id FROM legacy_track_refs WHERE legacy_id=NEW.track_id),NEW.track_id) AND video_id IS NOT NULL; INSERT INTO unresolved_playlist_items SELECT NEW.playlist_id,id,NEW.position FROM catalog_entries WHERE id=COALESCE((SELECT entry_id FROM legacy_track_refs WHERE legacy_id=NEW.track_id),NEW.track_id) AND video_id IS NULL; SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM catalog_entries WHERE id=COALESCE((SELECT entry_id FROM legacy_track_refs WHERE legacy_id=NEW.track_id),NEW.track_id)) THEN RAISE(ABORT,'Unknown track reference') END; END;
CREATE TRIGGER playlist_tracks_delete INSTEAD OF DELETE ON playlist_tracks BEGIN DELETE FROM playlist_items WHERE playlist_id=OLD.playlist_id AND video_id=(SELECT video_id FROM catalog_entries WHERE id=OLD.track_id); DELETE FROM unresolved_playlist_items WHERE playlist_id=OLD.playlist_id AND entry_id=OLD.track_id; END;
CREATE TRIGGER catalog_tracks_update INSTEAD OF UPDATE ON catalog_tracks BEGIN UPDATE recordings SET genre=CASE WHEN NEW.genre IS NOT OLD.genre THEN NEW.genre ELSE genre END,bpm=CASE WHEN NEW.bpm IS NOT OLD.bpm THEN NEW.bpm ELSE bpm END,energy=CASE WHEN NEW.energy IS NOT OLD.energy THEN NEW.energy ELSE energy END,danceability=CASE WHEN NEW.danceability IS NOT OLD.danceability THEN NEW.danceability ELSE danceability END,mb_recording_id=CASE WHEN NEW.mb_recording_id IS NOT OLD.mb_recording_id THEN NEW.mb_recording_id ELSE mb_recording_id END,music_key=CASE WHEN NEW.music_key IS NOT OLD.music_key THEN NEW.music_key ELSE music_key END,music_scale=CASE WHEN NEW.music_scale IS NOT OLD.music_scale THEN NEW.music_scale ELSE music_scale END,mood_happy=CASE WHEN NEW.mood_happy IS NOT OLD.mood_happy THEN NEW.mood_happy ELSE mood_happy END,mood_sad=CASE WHEN NEW.mood_sad IS NOT OLD.mood_sad THEN NEW.mood_sad ELSE mood_sad END,mood_relaxed=CASE WHEN NEW.mood_relaxed IS NOT OLD.mood_relaxed THEN NEW.mood_relaxed ELSE mood_relaxed END,mood_acoustic=CASE WHEN NEW.mood_acoustic IS NOT OLD.mood_acoustic THEN NEW.mood_acoustic ELSE mood_acoustic END,instrumental=CASE WHEN NEW.instrumental IS NOT OLD.instrumental THEN NEW.instrumental ELSE instrumental END,first_enriched_at=CASE WHEN NEW.first_enriched_at IS NOT OLD.first_enriched_at THEN NEW.first_enriched_at ELSE first_enriched_at END,last_enriched_at=CASE WHEN NEW.last_enriched_at IS NOT OLD.last_enriched_at THEN NEW.last_enriched_at ELSE last_enriched_at END,created_at=CASE WHEN NEW.created_at IS NOT OLD.created_at THEN NEW.created_at ELSE created_at END WHERE id=OLD.recording_id; UPDATE youtube_items SET title=CASE WHEN NEW.title IS NOT OLD.title THEN NEW.title ELSE title END,artist=CASE WHEN NEW.artist IS NOT OLD.artist THEN NEW.artist ELSE artist END,orig_title=CASE WHEN NEW.orig_title IS NOT OLD.orig_title THEN NEW.orig_title ELSE orig_title END,orig_artist=CASE WHEN NEW.orig_artist IS NOT OLD.orig_artist THEN NEW.orig_artist ELSE orig_artist END,album=CASE WHEN NEW.album IS NOT OLD.album THEN NEW.album ELSE album END,duration_s=CASE WHEN NEW.duration_s IS NOT OLD.duration_s THEN NEW.duration_s ELSE duration_s END,available=CASE WHEN NEW.available IS NOT OLD.available THEN NEW.available ELSE available END,video_type=CASE WHEN NEW.video_type IS NOT OLD.video_type THEN NEW.video_type ELSE video_type END,artist_browse_id=CASE WHEN NEW.artist_browse_id IS NOT OLD.artist_browse_id THEN NEW.artist_browse_id ELSE artist_browse_id END,album_browse_id=CASE WHEN NEW.album_browse_id IS NOT OLD.album_browse_id THEN NEW.album_browse_id ELSE album_browse_id END,thumbnail=CASE WHEN NEW.thumbnail IS NOT OLD.thumbnail THEN NEW.thumbnail ELSE thumbnail END,mb_year=CASE WHEN NEW.mb_year IS NOT OLD.mb_year THEN NEW.mb_year ELSE mb_year END,loudness=CASE WHEN NEW.loudness IS NOT OLD.loudness THEN NEW.loudness ELSE loudness END,dynamic_complexity=CASE WHEN NEW.dynamic_complexity IS NOT OLD.dynamic_complexity THEN NEW.dynamic_complexity ELSE dynamic_complexity END,popularity=CASE WHEN NEW.popularity IS NOT OLD.popularity THEN NEW.popularity ELSE popularity END,gain=CASE WHEN NEW.gain IS NOT OLD.gain THEN NEW.gain ELSE gain END,label=CASE WHEN NEW.label IS NOT OLD.label THEN NEW.label ELSE label END WHERE video_id=OLD.video_id; UPDATE unresolved_items SET title=CASE WHEN NEW.title IS NOT OLD.title THEN NEW.title ELSE title END,artist=CASE WHEN NEW.artist IS NOT OLD.artist THEN NEW.artist ELSE artist END,orig_title=CASE WHEN NEW.orig_title IS NOT OLD.orig_title THEN NEW.orig_title ELSE orig_title END,orig_artist=CASE WHEN NEW.orig_artist IS NOT OLD.orig_artist THEN NEW.orig_artist ELSE orig_artist END,album=CASE WHEN NEW.album IS NOT OLD.album THEN NEW.album ELSE album END,duration_s=CASE WHEN NEW.duration_s IS NOT OLD.duration_s THEN NEW.duration_s ELSE duration_s END,available=CASE WHEN NEW.available IS NOT OLD.available THEN NEW.available ELSE available END,video_type=CASE WHEN NEW.video_type IS NOT OLD.video_type THEN NEW.video_type ELSE video_type END,artist_browse_id=CASE WHEN NEW.artist_browse_id IS NOT OLD.artist_browse_id THEN NEW.artist_browse_id ELSE artist_browse_id END,album_browse_id=CASE WHEN NEW.album_browse_id IS NOT OLD.album_browse_id THEN NEW.album_browse_id ELSE album_browse_id END,thumbnail=CASE WHEN NEW.thumbnail IS NOT OLD.thumbnail THEN NEW.thumbnail ELSE thumbnail END,mb_year=CASE WHEN NEW.mb_year IS NOT OLD.mb_year THEN NEW.mb_year ELSE mb_year END,loudness=CASE WHEN NEW.loudness IS NOT OLD.loudness THEN NEW.loudness ELSE loudness END,dynamic_complexity=CASE WHEN NEW.dynamic_complexity IS NOT OLD.dynamic_complexity THEN NEW.dynamic_complexity ELSE dynamic_complexity END,popularity=CASE WHEN NEW.popularity IS NOT OLD.popularity THEN NEW.popularity ELSE popularity END,gain=CASE WHEN NEW.gain IS NOT OLD.gain THEN NEW.gain ELSE gain END,label=CASE WHEN NEW.label IS NOT OLD.label THEN NEW.label ELSE label END WHERE entry_id=OLD.id; END;
CREATE TRIGGER tracks_update INSTEAD OF UPDATE ON tracks BEGIN UPDATE recordings SET genre=CASE WHEN NEW.genre IS NOT OLD.genre THEN NEW.genre ELSE genre END,bpm=CASE WHEN NEW.bpm IS NOT OLD.bpm THEN NEW.bpm ELSE bpm END,energy=CASE WHEN NEW.energy IS NOT OLD.energy THEN NEW.energy ELSE energy END,danceability=CASE WHEN NEW.danceability IS NOT OLD.danceability THEN NEW.danceability ELSE danceability END,mb_recording_id=CASE WHEN NEW.mb_recording_id IS NOT OLD.mb_recording_id THEN NEW.mb_recording_id ELSE mb_recording_id END,music_key=CASE WHEN NEW.music_key IS NOT OLD.music_key THEN NEW.music_key ELSE music_key END,music_scale=CASE WHEN NEW.music_scale IS NOT OLD.music_scale THEN NEW.music_scale ELSE music_scale END,mood_happy=CASE WHEN NEW.mood_happy IS NOT OLD.mood_happy THEN NEW.mood_happy ELSE mood_happy END,mood_sad=CASE WHEN NEW.mood_sad IS NOT OLD.mood_sad THEN NEW.mood_sad ELSE mood_sad END,mood_relaxed=CASE WHEN NEW.mood_relaxed IS NOT OLD.mood_relaxed THEN NEW.mood_relaxed ELSE mood_relaxed END,mood_acoustic=CASE WHEN NEW.mood_acoustic IS NOT OLD.mood_acoustic THEN NEW.mood_acoustic ELSE mood_acoustic END,instrumental=CASE WHEN NEW.instrumental IS NOT OLD.instrumental THEN NEW.instrumental ELSE instrumental END,first_enriched_at=CASE WHEN NEW.first_enriched_at IS NOT OLD.first_enriched_at THEN NEW.first_enriched_at ELSE first_enriched_at END,last_enriched_at=CASE WHEN NEW.last_enriched_at IS NOT OLD.last_enriched_at THEN NEW.last_enriched_at ELSE last_enriched_at END,created_at=CASE WHEN NEW.created_at IS NOT OLD.created_at THEN NEW.created_at ELSE created_at END WHERE id=OLD.recording_id; UPDATE youtube_items SET title=CASE WHEN NEW.title IS NOT OLD.title THEN NEW.title ELSE title END,artist=CASE WHEN NEW.artist IS NOT OLD.artist THEN NEW.artist ELSE artist END,orig_title=CASE WHEN NEW.orig_title IS NOT OLD.orig_title THEN NEW.orig_title ELSE orig_title END,orig_artist=CASE WHEN NEW.orig_artist IS NOT OLD.orig_artist THEN NEW.orig_artist ELSE orig_artist END,album=CASE WHEN NEW.album IS NOT OLD.album THEN NEW.album ELSE album END,duration_s=CASE WHEN NEW.duration_s IS NOT OLD.duration_s THEN NEW.duration_s ELSE duration_s END,available=CASE WHEN NEW.available IS NOT OLD.available THEN NEW.available ELSE available END,video_type=CASE WHEN NEW.video_type IS NOT OLD.video_type THEN NEW.video_type ELSE video_type END,artist_browse_id=CASE WHEN NEW.artist_browse_id IS NOT OLD.artist_browse_id THEN NEW.artist_browse_id ELSE artist_browse_id END,album_browse_id=CASE WHEN NEW.album_browse_id IS NOT OLD.album_browse_id THEN NEW.album_browse_id ELSE album_browse_id END,thumbnail=CASE WHEN NEW.thumbnail IS NOT OLD.thumbnail THEN NEW.thumbnail ELSE thumbnail END,mb_year=CASE WHEN NEW.mb_year IS NOT OLD.mb_year THEN NEW.mb_year ELSE mb_year END,loudness=CASE WHEN NEW.loudness IS NOT OLD.loudness THEN NEW.loudness ELSE loudness END,dynamic_complexity=CASE WHEN NEW.dynamic_complexity IS NOT OLD.dynamic_complexity THEN NEW.dynamic_complexity ELSE dynamic_complexity END,popularity=CASE WHEN NEW.popularity IS NOT OLD.popularity THEN NEW.popularity ELSE popularity END,gain=CASE WHEN NEW.gain IS NOT OLD.gain THEN NEW.gain ELSE gain END,label=CASE WHEN NEW.label IS NOT OLD.label THEN NEW.label ELSE label END WHERE video_id=OLD.video_id; UPDATE unresolved_items SET title=CASE WHEN NEW.title IS NOT OLD.title THEN NEW.title ELSE title END,artist=CASE WHEN NEW.artist IS NOT OLD.artist THEN NEW.artist ELSE artist END,orig_title=CASE WHEN NEW.orig_title IS NOT OLD.orig_title THEN NEW.orig_title ELSE orig_title END,orig_artist=CASE WHEN NEW.orig_artist IS NOT OLD.orig_artist THEN NEW.orig_artist ELSE orig_artist END,album=CASE WHEN NEW.album IS NOT OLD.album THEN NEW.album ELSE album END,duration_s=CASE WHEN NEW.duration_s IS NOT OLD.duration_s THEN NEW.duration_s ELSE duration_s END,available=CASE WHEN NEW.available IS NOT OLD.available THEN NEW.available ELSE available END,video_type=CASE WHEN NEW.video_type IS NOT OLD.video_type THEN NEW.video_type ELSE video_type END,artist_browse_id=CASE WHEN NEW.artist_browse_id IS NOT OLD.artist_browse_id THEN NEW.artist_browse_id ELSE artist_browse_id END,album_browse_id=CASE WHEN NEW.album_browse_id IS NOT OLD.album_browse_id THEN NEW.album_browse_id ELSE album_browse_id END,thumbnail=CASE WHEN NEW.thumbnail IS NOT OLD.thumbnail THEN NEW.thumbnail ELSE thumbnail END,mb_year=CASE WHEN NEW.mb_year IS NOT OLD.mb_year THEN NEW.mb_year ELSE mb_year END,loudness=CASE WHEN NEW.loudness IS NOT OLD.loudness THEN NEW.loudness ELSE loudness END,dynamic_complexity=CASE WHEN NEW.dynamic_complexity IS NOT OLD.dynamic_complexity THEN NEW.dynamic_complexity ELSE dynamic_complexity END,popularity=CASE WHEN NEW.popularity IS NOT OLD.popularity THEN NEW.popularity ELSE popularity END,gain=CASE WHEN NEW.gain IS NOT OLD.gain THEN NEW.gain ELSE gain END,label=CASE WHEN NEW.label IS NOT OLD.label THEN NEW.label ELSE label END WHERE entry_id=OLD.id; END;
CREATE VIEW discovered_tracks AS SELECT c.*,c.mb_year year,d.found_at,d.first_shown,d.last_shown,d.offered_count,c.last_enriched_at last_enriched,(SELECT source_token FROM discovery_sources s WHERE s.recording_id=d.recording_id ORDER BY s.found_at,source_token LIMIT 1) source_browse_id FROM discovery_memberships d JOIN catalog_tracks c ON c.id=d.entry_id;
CREATE TRIGGER discovered_tracks_delete INSTEAD OF DELETE ON discovered_tracks BEGIN DELETE FROM discovery_sources WHERE recording_id=OLD.recording_id; DELETE FROM discovery_memberships WHERE recording_id=OLD.recording_id; END;
CREATE TRIGGER discovered_tracks_update INSTEAD OF UPDATE ON discovered_tracks BEGIN UPDATE catalog_tracks SET genre=NEW.genre,bpm=NEW.bpm,energy=NEW.energy,danceability=NEW.danceability,mb_recording_id=NEW.mb_recording_id,music_key=NEW.music_key,music_scale=NEW.music_scale,mood_happy=NEW.mood_happy,mood_sad=NEW.mood_sad,mood_relaxed=NEW.mood_relaxed,mood_acoustic=NEW.mood_acoustic,instrumental=NEW.instrumental,mb_year=NEW.year,first_enriched_at=COALESCE(first_enriched_at,NEW.last_enriched),last_enriched_at=NEW.last_enriched WHERE id=OLD.id; UPDATE discovery_memberships SET first_shown=NEW.first_shown,last_shown=NEW.last_shown,offered_count=NEW.offered_count WHERE recording_id=OLD.recording_id; END;
CREATE VIEW catalog_enrichment_tracks AS SELECT c.*,r.id queue_order,CASE WHEN EXISTS(SELECT 1 FROM library_memberships lm JOIN catalog_entries e ON e.id=lm.entry_id WHERE e.recording_id=r.id) THEN 'library' ELSE 'discovery' END source FROM recordings r JOIN catalog_tracks c ON c.id=COALESCE((SELECT MIN(e.id) FROM catalog_entries e JOIN library_memberships lm ON lm.entry_id=e.id WHERE e.recording_id=r.id),(SELECT entry_id FROM discovery_memberships WHERE recording_id=r.id));
CREATE TRIGGER rec_served_impressions_subject AFTER INSERT ON rec_served_impressions BEGIN UPDATE rec_served_impressions SET raw_identity_key=NEW.identity_key,recording_id=COALESCE((SELECT recording_id FROM recording_redirects WHERE retired_id=COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))),COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))) WHERE rowid=NEW.rowid; UPDATE rec_served_impressions SET identity_key=COALESCE((SELECT identity_key FROM recordings WHERE id=rec_served_impressions.recording_id),identity_key) WHERE rowid=NEW.rowid; END;
CREATE TRIGGER rec_lane_impressions_subject AFTER INSERT ON rec_lane_impressions BEGIN UPDATE rec_lane_impressions SET raw_identity_key=NEW.identity_key,recording_id=COALESCE((SELECT recording_id FROM recording_redirects WHERE retired_id=COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))),COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))) WHERE rowid=NEW.rowid; UPDATE rec_lane_impressions SET identity_key=COALESCE((SELECT identity_key FROM recordings WHERE id=rec_lane_impressions.recording_id),identity_key) WHERE rowid=NEW.rowid; END;
CREATE TRIGGER feedback_subject AFTER INSERT ON rec_feedback BEGIN UPDATE rec_feedback SET recording_id=(SELECT id FROM recordings WHERE identity_key=NEW.item_key),target_type=CASE WHEN EXISTS(SELECT 1 FROM recordings WHERE identity_key=NEW.item_key) THEN 'recording' ELSE target_type END WHERE rowid=NEW.rowid; END;
CREATE TABLE rec_response_events (
        id INTEGER PRIMARY KEY, event_id TEXT NOT NULL, kind TEXT NOT NULL,
        identity_key TEXT NOT NULL, at REAL NOT NULL, is_generated INTEGER NOT NULL DEFAULT 0,
        UNIQUE(event_id, kind, identity_key)
    );
CREATE INDEX ix_rec_response_at ON rec_response_events(at);
CREATE TRIGGER play_events_subject AFTER INSERT ON play_events BEGIN UPDATE play_events SET raw_identity_key=NEW.identity_key,recording_id=CASE WHEN NULLIF(trim(NEW.video_id),'') IS NOT NULL THEN (SELECT recording_id FROM youtube_items WHERE video_id=NEW.video_id) ELSE COALESCE((SELECT recording_id FROM recording_redirects WHERE retired_id=COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))),COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))) END WHERE rowid=NEW.rowid; UPDATE play_events SET identity_key=COALESCE((SELECT identity_key FROM recordings WHERE id=play_events.recording_id),CASE WHEN NULLIF(trim(NEW.video_id),'') IS NOT NULL AND EXISTS(SELECT 1 FROM recordings WHERE identity_key=NEW.identity_key) THEN '@unresolved-video:'||NEW.video_id ELSE identity_key END) WHERE rowid=NEW.rowid; END;
CREATE TABLE takeout_imports (
    id INTEGER PRIMARY KEY,
    identity_id INTEGER NOT NULL REFERENCES identities(id),
    fingerprint TEXT NOT NULL,
    imported_at REAL NOT NULL,
    observed_start REAL,
    observed_end REAL,
    unparsed_dates INTEGER NOT NULL CHECK(unparsed_dates >= 0),
    account_verified INTEGER NOT NULL DEFAULT 0 CHECK(account_verified IN (0,1)),
    complete INTEGER NOT NULL DEFAULT 0 CHECK(complete IN (0,1)),
    coverage_start REAL,
    coverage_end REAL,
    CHECK(coverage_start IS NULL OR coverage_end > coverage_start)
);
CREATE TABLE enrichment_provider_state (
    recording_id INTEGER NOT NULL REFERENCES recordings(id),
    provider TEXT NOT NULL,
    cycle REAL NOT NULL,
    at REAL NOT NULL,
    status TEXT NOT NULL,
    failures INTEGER NOT NULL,
    retry_at REAL NOT NULL,
    error TEXT NOT NULL,
    PRIMARY KEY(recording_id,provider)
);
CREATE TABLE enrichment_provider_cooldowns (
    provider TEXT PRIMARY KEY NOT NULL,
    failures INTEGER NOT NULL,
    retry_at REAL NOT NULL,
    error TEXT NOT NULL
);
CREATE TABLE enrichment_provider_config (
    provider TEXT PRIMARY KEY NOT NULL,
    fingerprint TEXT NOT NULL,
    status TEXT NOT NULL
);
CREATE TABLE enrichment_provider_jobs (
    recording_id INTEGER NOT NULL REFERENCES recordings(id),
    provider TEXT NOT NULL,
    PRIMARY KEY(recording_id,provider)
);
CREATE TABLE enrichment_artwork (
    entry_id INTEGER PRIMARY KEY REFERENCES catalog_entries(id),
    release_ids_json TEXT NOT NULL,
    status TEXT NOT NULL,
    failures INTEGER NOT NULL,
    retry_at REAL NOT NULL,
    error TEXT NOT NULL
);
CREATE TABLE album_share_snapshots (
    browse_id TEXT PRIMARY KEY NOT NULL,
    title TEXT NOT NULL,
    video_ids_json TEXT NOT NULL
);
CREATE TABLE artists (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,provisional INTEGER NOT NULL CHECK(provisional IN (0,1)));
CREATE TABLE artist_provider_ids (provider TEXT NOT NULL,provider_id TEXT NOT NULL,artist_id INTEGER NOT NULL REFERENCES artists(id),PRIMARY KEY(provider,provider_id));
CREATE INDEX ix_artist_provider_subject ON artist_provider_ids(artist_id);
CREATE TABLE artist_aliases (artist_id INTEGER NOT NULL REFERENCES artists(id),alias TEXT NOT NULL,source TEXT NOT NULL,PRIMARY KEY(artist_id,alias,source));
CREATE INDEX ix_artist_alias ON artist_aliases(alias,artist_id);
CREATE TABLE entry_artists (entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),position INTEGER NOT NULL CHECK(position>=0),artist_id INTEGER NOT NULL REFERENCES artists(id),credit TEXT NOT NULL,source TEXT NOT NULL,PRIMARY KEY(entry_id,position));
CREATE INDEX ix_entry_artist_subject ON entry_artists(artist_id,entry_id);
CREATE TABLE artist_credits (id INTEGER PRIMARY KEY AUTOINCREMENT,display_credit TEXT NOT NULL,content_digest TEXT NOT NULL UNIQUE CHECK(length(content_digest)=64 AND content_digest NOT GLOB '*[^0-9a-f]*'),member_count INTEGER NOT NULL CHECK(typeof(member_count)='integer' AND member_count BETWEEN 1 AND 128),complete INTEGER NOT NULL DEFAULT 0 CHECK(typeof(complete)='integer' AND complete IN (0,1)));
CREATE TABLE artist_credit_members (credit_id INTEGER NOT NULL REFERENCES artist_credits(id),position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 127),artist_id INTEGER REFERENCES artists(id),credit_text TEXT NOT NULL CHECK(length(credit_text)>0),provider TEXT,raw_id TEXT,raw_browse_id TEXT,role TEXT,presence INTEGER NOT NULL CHECK(typeof(presence)='integer' AND presence BETWEEN 0 AND 7),CHECK((provider IS NULL)=(COALESCE(NULLIF(raw_id,''),NULLIF(raw_browse_id,'')) IS NULL)),CHECK((presence&1)<>0 OR raw_id IS NULL),CHECK((presence&2)<>0 OR raw_browse_id IS NULL),CHECK((presence&4)<>0 OR role IS NULL),PRIMARY KEY(credit_id,position)) WITHOUT ROWID;
CREATE INDEX ix_credit_member_artist ON artist_credit_members(artist_id,credit_id) WHERE artist_id IS NOT NULL;
CREATE TABLE artist_credit_observations (id INTEGER PRIMARY KEY AUTOINCREMENT,entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),credit_id INTEGER NOT NULL REFERENCES artist_credits(id),source TEXT NOT NULL CHECK(length(source)>0),delivery_key TEXT CHECK(delivery_key IS NULL OR length(delivery_key)>0),first_seen REAL CHECK(first_seen IS NULL OR (typeof(first_seen) IN ('integer','real') AND first_seen BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)),last_seen REAL CHECK(last_seen IS NULL OR (typeof(last_seen) IN ('integer','real') AND last_seen BETWEEN -1.7976931348623157e308 AND 1.7976931348623157e308)),processing_count INTEGER NOT NULL CHECK(typeof(processing_count)='integer' AND processing_count>0),capture_kind TEXT NOT NULL CHECK(capture_kind IN ('legacy_capture','selection_snapshot','capture','provider_delivery','identity_reconciliation')),CHECK((first_seen IS NULL AND last_seen IS NULL) OR (first_seen IS NOT NULL AND last_seen IS NOT NULL AND first_seen<=last_seen)),CHECK((capture_kind IN ('provider_delivery','identity_reconciliation'))=(delivery_key IS NOT NULL)));
CREATE UNIQUE INDEX ix_credit_delivery ON artist_credit_observations(entry_id,source,delivery_key) WHERE delivery_key IS NOT NULL;
CREATE INDEX ix_credit_entry_source ON artist_credit_observations(entry_id,source,id);
CREATE INDEX ix_credit_observation_content ON artist_credit_observations(credit_id,id);
CREATE TABLE artist_credit_capture_heads (entry_id INTEGER NOT NULL REFERENCES catalog_entries(id),source TEXT NOT NULL,observation_id INTEGER NOT NULL REFERENCES artist_credit_observations(id),PRIMARY KEY(entry_id,source)) WITHOUT ROWID;
CREATE INDEX ix_credit_capture_observation ON artist_credit_capture_heads(observation_id);
CREATE TABLE entry_artist_selections (entry_id INTEGER PRIMARY KEY NOT NULL REFERENCES catalog_entries(id),observation_id INTEGER NOT NULL REFERENCES artist_credit_observations(id)) WITHOUT ROWID;
CREATE INDEX ix_entry_artist_selection_observation ON entry_artist_selections(observation_id);
CREATE TRIGGER immutable_artist_credit BEFORE UPDATE OF id,display_credit,content_digest,member_count ON artist_credits BEGIN SELECT RAISE(ABORT,'Artist credit content is immutable'); END;
CREATE TRIGGER private_artist_credit BEFORE INSERT ON artist_credits WHEN NEW.complete<>0 BEGIN SELECT RAISE(ABORT,'Artist credit must be assembled privately'); END;
CREATE TRIGGER complete_artist_credit BEFORE UPDATE OF complete ON artist_credits WHEN OLD.complete<>0 OR NEW.complete<>1 OR OLD.member_count<>(SELECT count(*) FROM artist_credit_members WHERE credit_id=OLD.id) OR (SELECT min(position) FROM artist_credit_members WHERE credit_id=OLD.id)<>0 OR (SELECT max(position) FROM artist_credit_members WHERE credit_id=OLD.id)<>OLD.member_count-1 BEGIN SELECT RAISE(ABORT,'Artist credit membership is incomplete or sealed'); END;
CREATE TRIGGER immutable_artist_credit_member_insert BEFORE INSERT ON artist_credit_members WHEN EXISTS(SELECT 1 FROM artist_credits c WHERE c.id=NEW.credit_id AND c.complete=1) BEGIN SELECT RAISE(ABORT,'Artist credit members are immutable'); END;
CREATE TRIGGER immutable_artist_credit_member_update BEFORE UPDATE ON artist_credit_members WHEN EXISTS(SELECT 1 FROM artist_credits c WHERE c.id=OLD.credit_id AND c.complete=1) OR EXISTS(SELECT 1 FROM artist_credits c WHERE c.id=NEW.credit_id AND c.complete=1) BEGIN SELECT RAISE(ABORT,'Artist credit members are immutable'); END;
CREATE TRIGGER immutable_artist_credit_member_delete BEFORE DELETE ON artist_credit_members WHEN EXISTS(SELECT 1 FROM artist_credits c WHERE c.id=OLD.credit_id AND c.complete=1 AND EXISTS(SELECT 1 FROM artist_credit_observations o WHERE o.credit_id=c.id)) BEGIN SELECT RAISE(ABORT,'Artist credit members are immutable'); END;
CREATE TRIGGER complete_credit_observation BEFORE INSERT ON artist_credit_observations WHEN NOT EXISTS(SELECT 1 FROM artist_credits WHERE id=NEW.credit_id AND complete=1) BEGIN SELECT RAISE(ABORT,'Artist evidence requires complete credit content'); END;
CREATE TRIGGER immutable_credit_observation BEFORE UPDATE OF id,entry_id,credit_id,source,delivery_key,capture_kind ON artist_credit_observations BEGIN SELECT RAISE(ABORT,'Artist credit evidence identity is immutable'); END;
CREATE TRIGGER monotonic_credit_processing BEFORE UPDATE OF first_seen,last_seen,processing_count ON artist_credit_observations WHEN OLD.capture_kind IN ('legacy_capture','selection_snapshot') OR NEW.processing_count<>OLD.processing_count+1 OR (OLD.first_seen IS NOT NULL AND (NEW.first_seen IS NULL OR NEW.first_seen>OLD.first_seen)) OR (OLD.last_seen IS NOT NULL AND (NEW.last_seen IS NULL OR NEW.last_seen<OLD.last_seen)) BEGIN SELECT RAISE(ABORT,'Artist processing history must advance without rewriting captures'); END;
CREATE TRIGGER owned_artist_credit_capture_heads_insert BEFORE INSERT ON artist_credit_capture_heads WHEN NOT EXISTS(SELECT 1 FROM artist_credit_observations o WHERE o.id=NEW.observation_id AND o.entry_id=NEW.entry_id AND o.source=NEW.source) BEGIN SELECT RAISE(ABORT,'Selected artist evidence has a different owner'); END;
CREATE TRIGGER owned_artist_credit_capture_heads_update BEFORE UPDATE ON artist_credit_capture_heads WHEN NOT EXISTS(SELECT 1 FROM artist_credit_observations o WHERE o.id=NEW.observation_id AND o.entry_id=NEW.entry_id AND o.source=NEW.source) BEGIN SELECT RAISE(ABORT,'Selected artist evidence has a different owner'); END;
CREATE TRIGGER owned_entry_artist_selections_insert BEFORE INSERT ON entry_artist_selections WHEN NOT EXISTS(SELECT 1 FROM artist_credit_observations o WHERE o.id=NEW.observation_id AND o.entry_id=NEW.entry_id) BEGIN SELECT RAISE(ABORT,'Selected artist evidence has a different owner'); END;
CREATE TRIGGER owned_entry_artist_selections_update BEFORE UPDATE ON entry_artist_selections WHEN NOT EXISTS(SELECT 1 FROM artist_credit_observations o WHERE o.id=NEW.observation_id AND o.entry_id=NEW.entry_id) BEGIN SELECT RAISE(ABORT,'Selected artist evidence has a different owner'); END;
CREATE TABLE artist_similarity_targets (source_artist_id INTEGER NOT NULL REFERENCES artists(id),target_artist_id INTEGER NOT NULL REFERENCES artists(id),weight REAL NOT NULL,PRIMARY KEY(source_artist_id,target_artist_id));
