CREATE UNIQUE INDEX ix_unresolved_playlist_position ON unresolved_playlist_items(playlist_id,position);
CREATE INDEX ix_unresolved_playlist_entry ON unresolved_playlist_items(entry_id,playlist_id);
CREATE INDEX ix_play_event_recording_time ON play_events(recording_id,played_at);
CREATE INDEX ix_play_event_account_time ON play_events(identity_id,played_at DESC,id DESC);
CREATE INDEX ix_play_event_account_key_time ON play_events(identity_id,identity_key,played_at);
CREATE INDEX ix_play_event_account_playlist_time ON play_events(identity_id,playlist_ytm_id,played_at);
CREATE INDEX ix_player_event_account_playlist_time ON player_events(identity_id,playlist_ytm_id,at);
CREATE INDEX ix_mode_pick_mode_time ON rec_mode_picks(mode_id,created_at);
CREATE TRIGGER playlist_items_position_insert BEFORE INSERT ON playlist_items WHEN typeof(NEW.position)<>'integer' OR NEW.position<0 OR EXISTS(SELECT 1 FROM unresolved_playlist_items WHERE playlist_id=NEW.playlist_id AND position=NEW.position) BEGIN SELECT RAISE(ABORT,'Invalid or occupied playlist position'); END;
CREATE TRIGGER playlist_items_position_update BEFORE UPDATE ON playlist_items WHEN typeof(NEW.position)<>'integer' OR NEW.position<0 OR EXISTS(SELECT 1 FROM unresolved_playlist_items WHERE playlist_id=NEW.playlist_id AND position=NEW.position) BEGIN SELECT RAISE(ABORT,'Invalid or occupied playlist position'); END;
CREATE TRIGGER unresolved_playlist_items_position_insert BEFORE INSERT ON unresolved_playlist_items WHEN typeof(NEW.position)<>'integer' OR NEW.position<0 OR EXISTS(SELECT 1 FROM playlist_items WHERE playlist_id=NEW.playlist_id AND position=NEW.position) BEGIN SELECT RAISE(ABORT,'Invalid or occupied playlist position'); END;
CREATE TRIGGER unresolved_playlist_items_position_update BEFORE UPDATE ON unresolved_playlist_items WHEN typeof(NEW.position)<>'integer' OR NEW.position<0 OR EXISTS(SELECT 1 FROM playlist_items WHERE playlist_id=NEW.playlist_id AND position=NEW.position) BEGIN SELECT RAISE(ABORT,'Invalid or occupied playlist position'); END;
CREATE TRIGGER playlists_scope_insert BEFORE INSERT ON playlists WHEN NOT EXISTS(SELECT 1 FROM playlist_scopes s WHERE s.ref=NEW.scope_ref AND s.provider_id=NEW.ytm_playlist_id AND ((s.kind='account' AND s.identity_id=NEW.identity_id AND s.provider_id IN ('LM','SE')) OR (s.kind='shared' AND s.identity_id IS NULL AND s.provider_id NOT IN ('LM','SE')))) BEGIN SELECT RAISE(ABORT,'Playlist scope does not match its account and provider'); END;
CREATE TRIGGER playlists_scope_update BEFORE UPDATE ON playlists WHEN NOT EXISTS(SELECT 1 FROM playlist_scopes s WHERE s.ref=NEW.scope_ref AND s.provider_id=NEW.ytm_playlist_id AND ((s.kind='account' AND s.identity_id=NEW.identity_id AND s.provider_id IN ('LM','SE')) OR (s.kind='shared' AND s.identity_id IS NULL AND s.provider_id NOT IN ('LM','SE')))) BEGIN SELECT RAISE(ABORT,'Playlist scope does not match its account and provider'); END;
CREATE TRIGGER playlists_membership_insert BEFORE INSERT ON playlists WHEN EXISTS(SELECT 1 FROM playlist_membership_refs m WHERE m.id=NEW.id AND (m.scope_ref IS NOT NEW.scope_ref OR m.identity_id IS NOT NEW.identity_id)) BEGIN SELECT RAISE(ABORT,'Playlist membership ID already belongs to retained history'); END;
CREATE TRIGGER playlists_membership_update BEFORE UPDATE ON playlists WHEN NEW.id IS NOT OLD.id OR NEW.scope_ref IS NOT OLD.scope_ref OR NEW.identity_id IS NOT OLD.identity_id BEGIN SELECT RAISE(ABORT,'Playlist membership identity is immutable'); END;
CREATE TRIGGER playlists_membership_record AFTER INSERT ON playlists BEGIN INSERT OR IGNORE INTO playlist_membership_refs(id,scope_ref,identity_id) VALUES (NEW.id,NEW.scope_ref,NEW.identity_id); SELECT CASE WHEN EXISTS(SELECT 1 FROM playlist_membership_refs m WHERE m.id=NEW.id AND (m.scope_ref IS NOT NEW.scope_ref OR m.identity_id IS NOT NEW.identity_id)) THEN RAISE(ABORT,'Playlist membership ID already belongs to retained history') END; END;
CREATE TRIGGER playlist_membership_refs_update BEFORE UPDATE ON playlist_membership_refs WHEN NEW.id IS NOT OLD.id OR NEW.scope_ref IS NOT OLD.scope_ref OR NEW.identity_id IS NOT OLD.identity_id BEGIN SELECT RAISE(ABORT,'Retained playlist membership identity is immutable'); END;
CREATE TRIGGER playlist_membership_refs_delete BEFORE DELETE ON playlist_membership_refs WHEN EXISTS(SELECT 1 FROM playlists WHERE id=OLD.id) BEGIN SELECT RAISE(ABORT,'Playlist still references this membership'); END;
CREATE TABLE listening_calendars (identity_id INTEGER PRIMARY KEY REFERENCES identities(id),timezone TEXT NOT NULL,confirmed INTEGER NOT NULL CHECK(confirmed IN (0,1)));
CREATE TABLE play_event_sources (event_id INTEGER NOT NULL REFERENCES play_events(id) ON DELETE CASCADE,source TEXT NOT NULL,PRIMARY KEY(event_id,source));
CREATE TABLE play_event_calendar (event_id INTEGER PRIMARY KEY REFERENCES play_events(id) ON DELETE CASCADE,day TEXT NOT NULL CHECK(date(day) IS NOT NULL AND date(day)=day),timezone TEXT NOT NULL);
CREATE INDEX ix_play_event_source ON play_event_sources(source,event_id);
CREATE INDEX ix_play_event_calendar_day ON play_event_calendar(day,event_id);
CREATE TRIGGER play_events_listening_insert AFTER INSERT ON play_events BEGIN
INSERT INTO play_event_sources(event_id,source) VALUES (NEW.id,COALESCE(NULLIF(NEW.source,''),'unknown'));
INSERT INTO play_event_calendar(event_id,day,timezone) VALUES (NEW.id,date(NEW.played_at,'unixepoch'),'UTC');
END;
CREATE TABLE artist_redirects (retired_id INTEGER PRIMARY KEY REFERENCES artists(id),artist_id INTEGER NOT NULL REFERENCES artists(id),source TEXT NOT NULL,created_at REAL NOT NULL,CHECK(retired_id<>artist_id));
CREATE INDEX ix_artist_redirect_target ON artist_redirects(artist_id);
CREATE TRIGGER artist_redirect_insert BEFORE INSERT ON artist_redirects WHEN EXISTS(SELECT 1 FROM artist_redirects WHERE retired_id=NEW.artist_id) OR NOT EXISTS(SELECT 1 FROM artists WHERE id=NEW.retired_id AND provisional=1) OR EXISTS(SELECT 1 FROM artist_provider_ids WHERE artist_id=NEW.retired_id) OR NOT EXISTS(SELECT 1 FROM artists a JOIN artist_provider_ids p ON p.artist_id=a.id WHERE a.id=NEW.artist_id AND a.provisional=0) BEGIN SELECT RAISE(ABORT,'Artist redirect requires a provisional source and canonical target'); END;
CREATE TRIGGER artist_redirect_update BEFORE UPDATE ON artist_redirects WHEN NEW.retired_id<>OLD.retired_id OR EXISTS(SELECT 1 FROM artist_redirects WHERE retired_id=NEW.artist_id) OR NOT EXISTS(SELECT 1 FROM artists WHERE id=NEW.retired_id AND provisional=1) OR EXISTS(SELECT 1 FROM artist_provider_ids WHERE artist_id=NEW.retired_id) OR NOT EXISTS(SELECT 1 FROM artists a JOIN artist_provider_ids p ON p.artist_id=a.id WHERE a.id=NEW.artist_id AND a.provisional=0) BEGIN SELECT RAISE(ABORT,'Artist redirect requires a provisional source and canonical target'); END;
CREATE TRIGGER discovery_membership_insert BEFORE INSERT ON discovery_memberships WHEN NOT EXISTS(SELECT 1 FROM catalog_entries e WHERE e.id=NEW.entry_id AND e.recording_id=NEW.recording_id) BEGIN SELECT RAISE(ABORT,'Discovery representative belongs to another recording'); END;
CREATE TRIGGER discovery_membership_update BEFORE UPDATE ON discovery_memberships WHEN NOT EXISTS(SELECT 1 FROM catalog_entries e WHERE e.id=NEW.entry_id AND e.recording_id=NEW.recording_id) BEGIN SELECT RAISE(ABORT,'Discovery representative belongs to another recording'); END;
CREATE TRIGGER discovery_entry_reassociation BEFORE UPDATE OF recording_id ON catalog_entries WHEN EXISTS(SELECT 1 FROM discovery_memberships d WHERE d.entry_id=OLD.id AND d.recording_id<>NEW.recording_id) BEGIN SELECT RAISE(ABORT,'Replace discovery representative before reassociation'); END;
CREATE INDEX ix_artist_provisional_name ON artists(name) WHERE provisional=1;
CREATE TABLE discovery_artist_sources (artist_id INTEGER NOT NULL REFERENCES artists(id),source TEXT NOT NULL,identity_id INTEGER REFERENCES identities(id),score REAL NOT NULL,PRIMARY KEY(artist_id,source));
CREATE INDEX discovery_artist_sources_identity ON discovery_artist_sources(identity_id,source);
CREATE TABLE spotify_history_listens (identity_id INTEGER NOT NULL REFERENCES identities(id),track_uri TEXT NOT NULL,ended_at REAL NOT NULL,event_id INTEGER REFERENCES play_events(id) ON DELETE SET NULL,artist_id INTEGER REFERENCES artists(id),PRIMARY KEY(identity_id,track_uri,ended_at));
CREATE TABLE listening_capture_receipts (id INTEGER PRIMARY KEY,identity_id INTEGER NOT NULL REFERENCES identities(id),captured_at REAL NOT NULL);
CREATE INDEX ix_listening_capture_account_time ON listening_capture_receipts(identity_id,captured_at);
CREATE TABLE listening_observations (
id INTEGER PRIMARY KEY AUTOINCREMENT,
identity_id INTEGER NOT NULL REFERENCES identities(id),
raw_identity_key TEXT,
identity_key TEXT NOT NULL,
recording_id INTEGER REFERENCES recordings(id),
source_day TEXT CHECK(source_day IS NULL OR (date(source_day) IS NOT NULL AND date(source_day)=source_day)),
day TEXT CHECK(day IS NULL OR (date(day) IS NOT NULL AND date(day)=day)),
source TEXT NOT NULL,
timezone TEXT,
precision TEXT NOT NULL,
first_observed_at REAL NOT NULL,
last_observed_at REAL NOT NULL,
capture_id INTEGER REFERENCES listening_capture_receipts(id),
capture_item_id INTEGER UNIQUE,
CHECK((precision='calendar_day' AND timezone IS NOT NULL AND raw_identity_key IS NOT NULL
       AND source_day IS NOT NULL AND capture_id IS NULL AND capture_item_id IS NULL)
   OR (precision='legacy_unknown' AND timezone IS NULL
       AND capture_id IS NOT NULL AND capture_item_id IS NOT NULL)),
UNIQUE(identity_id,raw_identity_key,source_day,source,timezone));
CREATE INDEX ix_listening_observation_subject_day ON listening_observations(identity_key,day,identity_id);
CREATE INDEX ix_listening_observation_account_day ON listening_observations(identity_id,day);
CREATE INDEX ix_listening_observation_recording_day ON listening_observations(recording_id,day,identity_id);
CREATE INDEX ix_listening_observation_capture ON listening_observations(capture_id);
CREATE VIEW listening_evidence AS
SELECT CASE WHEN capture_item_id IS NOT NULL THEN 'capture:'||capture_item_id ELSE 'day:'||id END evidence_id,
       identity_id,identity_key,recording_id,day,source,timezone,
       precision,last_observed_at observed_at,NULL event_id,0 is_generated
FROM listening_observations WHERE day IS NOT NULL
UNION ALL
SELECT 'event:'||pe.id||':'||s.source,pe.identity_id,pe.identity_key,pe.recording_id,c.day,
       s.source,c.timezone,'exact_timestamp',pe.played_at,pe.id,COALESCE(pe.is_generated,0)
FROM play_events pe JOIN play_event_calendar c ON c.event_id=pe.id
JOIN play_event_sources s ON s.event_id=pe.id;
CREATE VIEW listening_days AS
SELECT identity_id,identity_key,MIN(recording_id) recording_id,day,
       CAST(strftime('%s',day||' 12:00:00') AS REAL) day_ts,
       MAX(CASE WHEN event_id IS NOT NULL THEN observed_at END) last_event_at,
       MAX(observed_at) last_observed_at,
       CASE WHEN MIN(source)=MAX(source) THEN MIN(source) ELSE 'multiple' END source
FROM eligible_listening_evidence GROUP BY identity_id,identity_key,day;
CREATE VIEW listening_daily_items AS
SELECT identity_id||':'||day||':'||identity_key rowid,identity_id||':'||day snapshot_id,
       identity_key,recording_id,source,day,identity_id,last_event_at,last_observed_at
FROM listening_days;
CREATE VIEW listening_daily_snapshots AS
SELECT identity_id||':'||day id,identity_id,day_ts taken_at,day
FROM listening_days GROUP BY identity_id,day;
CREATE VIEW listening_activity AS
SELECT pe.identity_id,pe.identity_key,pe.recording_id,c.day,pe.played_at at,
       'exact_timestamp' precision,pe.id event_id
FROM play_events pe JOIN play_event_calendar c ON c.event_id=pe.id
WHERE COALESCE(pe.is_generated,0)=0
UNION ALL
SELECT d.identity_id,d.identity_key,d.recording_id,d.day,d.day_ts,
       CASE WHEN EXISTS (SELECT 1 FROM eligible_listening_evidence e
           WHERE e.identity_id=d.identity_id AND e.identity_key=d.identity_key AND e.day=d.day
           AND e.precision='calendar_day') THEN 'calendar_day' ELSE 'legacy_unknown' END,
       NULL FROM listening_days d
WHERE NOT EXISTS (SELECT 1 FROM play_events pe JOIN play_event_calendar c ON c.event_id=pe.id
    WHERE pe.identity_id=d.identity_id AND pe.identity_key=d.identity_key AND c.day=d.day
    AND COALESCE(pe.is_generated,0)=0);
CREATE TABLE rec_change_queue (kind TEXT NOT NULL,item TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(kind,item));
CREATE INDEX ix_rec_playlist_scope_cursor ON playlists(scope_ref,id);
CREATE INDEX ix_rec_album_cursor ON album_tracks(album_id,id);
CREATE INDEX ix_rec_feedback_key ON rec_feedback(item_key,kind);
CREATE INDEX ix_rec_feedback_recent ON rec_feedback(kind,created_at DESC);
CREATE INDEX ix_player_event_recent ON player_events(at DESC,id DESC);
CREATE INDEX ix_rec_served_model ON rec_served_impressions(model_version);
CREATE INDEX ix_rec_served_pool ON rec_served_impressions(CAST(json_extract(provenance,'$.pool_policy') AS TEXT));
CREATE VIEW eligible_listening_evidence AS
        SELECT CASE WHEN o.capture_item_id IS NOT NULL THEN 'capture:'||o.capture_item_id
                    ELSE 'day:'||o.id END evidence_id,
               o.identity_id,o.identity_key,o.recording_id,o.day,o.source,o.timezone,
               o.precision,o.last_observed_at observed_at,NULL event_id,0 is_generated
        FROM listening_observations o WHERE o.day IS NOT NULL AND (
            o.source<>'ytm_history' OR NOT EXISTS (
                SELECT 1 FROM play_events pe JOIN play_event_calendar c ON c.event_id=pe.id
                JOIN play_event_sources s ON s.event_id=pe.id
                WHERE pe.identity_id=o.identity_id AND pe.identity_key=o.identity_key
                  AND c.day=o.day AND pe.is_generated=1)
            OR EXISTS (
                SELECT 1 FROM play_events pe JOIN play_event_calendar c ON c.event_id=pe.id
                JOIN play_event_sources s ON s.event_id=pe.id
                WHERE pe.identity_id=o.identity_id AND pe.identity_key=o.identity_key
                  AND c.day=o.day AND COALESCE(pe.is_generated,0)=0)
            OR EXISTS (
                SELECT 1 FROM listening_observations independent
                WHERE independent.identity_id=o.identity_id AND independent.identity_key=o.identity_key
                  AND independent.day=o.day AND independent.source<>'ytm_history'))
        UNION ALL
        SELECT 'event:'||pe.id||':'||s.source,pe.identity_id,pe.identity_key,pe.recording_id,c.day,
               s.source,c.timezone,'exact_timestamp',pe.played_at,pe.id,COALESCE(pe.is_generated,0)
        FROM play_events pe JOIN play_event_calendar c ON c.event_id=pe.id
        JOIN play_event_sources s ON s.event_id=pe.id WHERE COALESCE(pe.is_generated,0)=0;
CREATE VIEW listening_day_counts AS
        SELECT identity_key,COUNT(*) plays FROM (
            SELECT DISTINCT identity_id,identity_key,day FROM eligible_listening_evidence
        ) GROUP BY identity_key;
CREATE TRIGGER rec_capture_recordings_insert AFTER INSERT ON recordings BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_recordings_delete AFTER DELETE ON recordings BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_recordings_update AFTER UPDATE ON recordings WHEN OLD.identity_key IS NOT NEW.identity_key OR OLD.genre IS NOT NEW.genre OR OLD.bpm IS NOT NEW.bpm OR OLD.energy IS NOT NEW.energy OR OLD.danceability IS NOT NEW.danceability OR OLD.music_key IS NOT NEW.music_key OR OLD.music_scale IS NOT NEW.music_scale OR OLD.mood_happy IS NOT NEW.mood_happy OR OLD.mood_sad IS NOT NEW.mood_sad OR OLD.mood_relaxed IS NOT NEW.mood_relaxed OR OLD.mood_acoustic IS NOT NEW.mood_acoustic OR OLD.instrumental IS NOT NEW.instrumental BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_youtube_items_insert AFTER INSERT ON youtube_items BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_youtube_items_delete AFTER DELETE ON youtube_items BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_youtube_items_update AFTER UPDATE ON youtube_items WHEN OLD.recording_id IS NOT NEW.recording_id OR OLD.available IS NOT NEW.available OR OLD.title IS NOT NEW.title OR OLD.artist IS NOT NEW.artist OR OLD.album IS NOT NEW.album OR OLD.mb_year IS NOT NEW.mb_year OR OLD.duration_s IS NOT NEW.duration_s OR OLD.video_type IS NOT NEW.video_type OR OLD.loudness IS NOT NEW.loudness OR OLD.dynamic_complexity IS NOT NEW.dynamic_complexity BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_catalog_entries_insert AFTER INSERT ON catalog_entries BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_catalog_entries_delete AFTER DELETE ON catalog_entries BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_catalog_entries_update AFTER UPDATE ON catalog_entries WHEN OLD.recording_id IS NOT NEW.recording_id OR OLD.video_id IS NOT NEW.video_id BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_library_memberships_insert AFTER INSERT ON library_memberships BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_library_memberships_delete AFTER DELETE ON library_memberships BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_library_memberships_update AFTER UPDATE ON library_memberships WHEN OLD.entry_id IS NOT NEW.entry_id BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_playlist_items_insert AFTER INSERT ON playlist_items BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_playlist_items_delete AFTER DELETE ON playlist_items BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
CREATE TRIGGER rec_capture_playlist_items_update AFTER UPDATE ON playlist_items WHEN OLD.playlist_id IS NOT NEW.playlist_id OR OLD.video_id IS NOT NEW.video_id BEGIN INSERT INTO rec_change_queue(kind,item) VALUES ('refresh','') ON CONFLICT(kind,item) DO UPDATE SET revision=revision+1; END;
