CREATE TABLE recording_embeddings (recording_id INTEGER NOT NULL REFERENCES recordings(id),space TEXT NOT NULL CHECK(space IN ('collaborative','content_library','content_discovery')),model_version TEXT NOT NULL CHECK(length(model_version)>0),dimensions INTEGER NOT NULL CHECK(typeof(dimensions)='integer' AND dimensions>0),vector BLOB NOT NULL CHECK(typeof(vector)='blob' AND length(vector)=dimensions*4),built_at REAL CHECK(built_at IS NULL OR (typeof(built_at) IN ('real','integer') AND abs(built_at)<=1.7976931348623157e308)),PRIMARY KEY(recording_id,space,model_version));
CREATE INDEX ix_recording_embedding_space ON recording_embeddings(space,model_version,recording_id);
CREATE TRIGGER recording_embeddings_owner_insert BEFORE INSERT ON recording_embeddings WHEN EXISTS(SELECT 1 FROM recording_redirects WHERE retired_id=NEW.recording_id) BEGIN SELECT RAISE(ABORT,'Embedding owner is retired'); END;
CREATE TRIGGER recording_embeddings_owner_update BEFORE UPDATE ON recording_embeddings WHEN EXISTS(SELECT 1 FROM recording_redirects WHERE retired_id=NEW.recording_id) BEGIN SELECT RAISE(ABORT,'Embedding owner is retired'); END;
CREATE TRIGGER retire_recording_embeddings_insert AFTER INSERT ON recording_redirects BEGIN DELETE FROM recording_embeddings WHERE recording_id=NEW.retired_id; END;
CREATE TRIGGER retire_recording_embeddings_update AFTER UPDATE ON recording_redirects BEGIN DELETE FROM recording_embeddings WHERE recording_id=NEW.retired_id; END;
CREATE TRIGGER recording_embeddings_basis_insert BEFORE INSERT ON recording_embeddings WHEN EXISTS(SELECT 1 FROM (SELECT model_version,dimensions FROM recording_embeddings WHERE space=NEW.space LIMIT 1) e WHERE e.model_version<>NEW.model_version OR e.dimensions<>NEW.dimensions) BEGIN SELECT RAISE(ABORT,'Mixed bases in an embedding space'); END;
CREATE TRIGGER recording_embeddings_basis_update BEFORE UPDATE ON recording_embeddings WHEN EXISTS(SELECT 1 FROM (SELECT model_version,dimensions FROM recording_embeddings WHERE space=NEW.space LIMIT 1) e WHERE e.model_version<>NEW.model_version OR e.dimensions<>NEW.dimensions) BEGIN SELECT RAISE(ABORT,'Mixed bases in an embedding space'); END;
CREATE TABLE artist_embeddings (artist_id INTEGER NOT NULL REFERENCES artists(id),space TEXT NOT NULL CHECK(space IN ('collaborative','content')),model_version TEXT NOT NULL CHECK(length(model_version)>0),dimensions INTEGER NOT NULL CHECK(typeof(dimensions)='integer' AND dimensions>0),vector BLOB NOT NULL CHECK(typeof(vector)='blob' AND length(vector)=dimensions*4),built_at REAL CHECK(built_at IS NULL OR (typeof(built_at) IN ('real','integer') AND abs(built_at)<=1.7976931348623157e308)),PRIMARY KEY(artist_id,space,model_version));
CREATE INDEX ix_artist_embedding_space ON artist_embeddings(space,model_version,artist_id);
CREATE TRIGGER artist_embeddings_owner_insert BEFORE INSERT ON artist_embeddings WHEN EXISTS(SELECT 1 FROM artist_redirects WHERE retired_id=NEW.artist_id) BEGIN SELECT RAISE(ABORT,'Embedding owner is retired'); END;
CREATE TRIGGER artist_embeddings_owner_update BEFORE UPDATE ON artist_embeddings WHEN EXISTS(SELECT 1 FROM artist_redirects WHERE retired_id=NEW.artist_id) BEGIN SELECT RAISE(ABORT,'Embedding owner is retired'); END;
CREATE TRIGGER retire_artist_embeddings_insert AFTER INSERT ON artist_redirects BEGIN DELETE FROM artist_embeddings WHERE artist_id=NEW.retired_id; END;
CREATE TRIGGER retire_artist_embeddings_update AFTER UPDATE ON artist_redirects BEGIN DELETE FROM artist_embeddings WHERE artist_id=NEW.retired_id; END;
CREATE TRIGGER artist_embeddings_basis_insert BEFORE INSERT ON artist_embeddings WHEN EXISTS(SELECT 1 FROM (SELECT model_version,dimensions FROM artist_embeddings WHERE space=NEW.space LIMIT 1) e WHERE e.model_version<>NEW.model_version OR e.dimensions<>NEW.dimensions) BEGIN SELECT RAISE(ABORT,'Mixed bases in an embedding space'); END;
CREATE TRIGGER artist_embeddings_basis_update BEFORE UPDATE ON artist_embeddings WHEN EXISTS(SELECT 1 FROM (SELECT model_version,dimensions FROM artist_embeddings WHERE space=NEW.space LIMIT 1) e WHERE e.model_version<>NEW.model_version OR e.dimensions<>NEW.dimensions) BEGIN SELECT RAISE(ABORT,'Mixed bases in an embedding space'); END;
CREATE TABLE unresolved_legacy_embeddings (source TEXT NOT NULL CHECK(source IN ('rec_vectors','rec_content_vectors','rec_discovered_content_vectors','rec_artist_vectors','rec_artist_content_vectors')),raw_key TEXT NOT NULL,model_version TEXT NOT NULL,dimensions INTEGER NOT NULL,vector BLOB NOT NULL,built_at REAL CHECK(built_at IS NULL OR (typeof(built_at) IN ('real','integer') AND abs(built_at)<=1.7976931348623157e308)),reason TEXT NOT NULL CHECK(reason IN ('missing_owner','ambiguous_owner','retired_owner')),PRIMARY KEY(source,raw_key),CHECK(typeof(dimensions)='integer' AND dimensions>0),CHECK(typeof(vector)='blob' AND length(vector)=dimensions*4)) WITHOUT ROWID;

