CREATE TABLE taste_groups (id INTEGER PRIMARY KEY AUTOINCREMENT,external_key TEXT NOT NULL UNIQUE CHECK(length(external_key)>0),legacy_mode_id INTEGER UNIQUE,created_at REAL NOT NULL CHECK(typeof(created_at) IN ('real','integer') AND abs(created_at)<=1.7976931348623157e308));
CREATE TABLE group_input_manifests (id INTEGER PRIMARY KEY AUTOINCREMENT,content_digest TEXT NOT NULL UNIQUE CHECK(length(content_digest)=64 AND content_digest NOT GLOB '*[^0-9a-f]*'),complete INTEGER NOT NULL DEFAULT 0 CHECK(typeof(complete)='integer' AND complete IN (0,1)));
CREATE TABLE group_recording_inputs (id INTEGER PRIMARY KEY AUTOINCREMENT,recording_id INTEGER NOT NULL REFERENCES recordings(id),input_digest TEXT NOT NULL CHECK(length(input_digest)=64 AND input_digest NOT GLOB '*[^0-9a-f]*'),UNIQUE(recording_id,input_digest),UNIQUE(id,recording_id));
