CREATE INDEX ix_group_manifest_input ON group_manifest_inputs(input_id,manifest_id);
CREATE TABLE unresolved_group_manifest_inputs (manifest_id INTEGER NOT NULL REFERENCES group_input_manifests(id),raw_key TEXT NOT NULL,input_digest TEXT NOT NULL CHECK(length(input_digest)=64 AND input_digest NOT GLOB '*[^0-9a-f]*'),reason TEXT NOT NULL CHECK(reason='missing_recording'),PRIMARY KEY(manifest_id,raw_key)) WITHOUT ROWID;
CREATE TABLE group_generations (id INTEGER PRIMARY KEY AUTOINCREMENT,external_key TEXT NOT NULL UNIQUE CHECK(length(external_key)>0),policy_version TEXT NOT NULL REFERENCES recommendation_policies(version),input_fingerprint TEXT NOT NULL,input_manifest_id INTEGER NOT NULL REFERENCES group_input_manifests(id),input_serial INTEGER NOT NULL CHECK(typeof(input_serial)='integer' AND input_serial>=0),created_at REAL NOT NULL CHECK(typeof(created_at) IN ('real','integer') AND abs(created_at)<=1.7976931348623157e308),metadata_filename TEXT NOT NULL CHECK(length(metadata_filename)>0),metadata_digest TEXT NOT NULL CHECK(length(metadata_digest)=64 AND metadata_digest NOT GLOB '*[^0-9a-f]*'),metadata_bytes INTEGER NOT NULL CHECK(typeof(metadata_bytes)='integer' AND metadata_bytes BETWEEN 1 AND 8388608),metadata_offset INTEGER NOT NULL CHECK(typeof(metadata_offset)='integer' AND metadata_offset>=29));
