CREATE INDEX ix_group_version_parent ON group_versions(parent_group_id,id);
CREATE INDEX ix_group_generation_manifest ON group_generations(input_manifest_id,id);
CREATE INDEX ix_group_generation_policy ON group_generations(policy_version,id);
CREATE INDEX ix_group_version_policy ON group_versions(policy_version,id);
CREATE TABLE group_version_aliases (external_version TEXT PRIMARY KEY NOT NULL CHECK(length(external_version)>0),group_version_id INTEGER NOT NULL REFERENCES group_versions(id),first_generation_id INTEGER NOT NULL REFERENCES group_generations(id),UNIQUE(external_version,group_version_id)) WITHOUT ROWID;
CREATE INDEX ix_group_version_alias_owner ON group_version_aliases(group_version_id,external_version);
CREATE TABLE generation_groups (generation_id INTEGER NOT NULL REFERENCES group_generations(id),group_id INTEGER NOT NULL REFERENCES taste_groups(id),group_version_id INTEGER NOT NULL,position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),external_version TEXT NOT NULL,PRIMARY KEY(generation_id,group_id),UNIQUE(generation_id,position),UNIQUE(generation_id,external_version),UNIQUE(generation_id,group_version_id),FOREIGN KEY(group_version_id,group_id) REFERENCES group_versions(id,group_id),FOREIGN KEY(external_version,group_version_id) REFERENCES group_version_aliases(external_version,group_version_id)) WITHOUT ROWID;
CREATE INDEX ix_generation_group_version ON generation_groups(group_version_id,generation_id);
CREATE INDEX ix_generation_group_alias ON generation_groups(external_version,generation_id);
CREATE TABLE group_members (group_version_id INTEGER NOT NULL REFERENCES group_versions(id),recording_id INTEGER NOT NULL REFERENCES recordings(id),similarity REAL NOT NULL CHECK(similarity BETWEEN 0 AND 1),support REAL NOT NULL CHECK(support BETWEEN 0 AND 1),input_id INTEGER,PRIMARY KEY(group_version_id,recording_id),FOREIGN KEY(input_id,recording_id) REFERENCES group_recording_inputs(id,recording_id)) WITHOUT ROWID;
