CREATE TABLE group_representatives (group_version_id INTEGER NOT NULL REFERENCES group_versions(id),position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position>=0),recording_id INTEGER REFERENCES recordings(id),raw_key TEXT,PRIMARY KEY(group_version_id,position),CHECK((recording_id IS NOT NULL AND raw_key IS NULL) OR (recording_id IS NULL AND raw_key IS NOT NULL))) WITHOUT ROWID;
