CREATE TABLE group_publications (generation_id INTEGER PRIMARY KEY NOT NULL REFERENCES group_generations(id),published_at REAL CHECK(published_at IS NULL OR (typeof(published_at) IN ('real','integer') AND abs(published_at)<=1.7976931348623157e308))) WITHOUT ROWID;
CREATE TABLE group_head (id INTEGER PRIMARY KEY CHECK(id=1),generation_id INTEGER NOT NULL REFERENCES group_publications(generation_id));
