CREATE TABLE group_lineage (source_alias TEXT NOT NULL,target_alias TEXT NOT NULL,source_version_id INTEGER NOT NULL,target_version_id INTEGER NOT NULL,relation TEXT NOT NULL CHECK(relation IN ('continuation','split','merge','legacy')),compatible INTEGER CHECK(compatible IS NULL OR (typeof(compatible)='integer' AND compatible IN (0,1))),old_share REAL CHECK(old_share IS NULL OR old_share BETWEEN 0 AND 1),new_share REAL CHECK(new_share IS NULL OR new_share BETWEEN 0 AND 1),overlap INTEGER CHECK(overlap IS NULL OR (typeof(overlap)='integer' AND overlap>=0)),evidence_filename TEXT NOT NULL CHECK(length(evidence_filename)>0),evidence_digest TEXT NOT NULL CHECK(length(evidence_digest)=64 AND evidence_digest NOT GLOB '*[^0-9a-f]*'),evidence_bytes INTEGER NOT NULL CHECK(typeof(evidence_bytes)='integer' AND evidence_bytes BETWEEN 1 AND 8388608),evidence_offset INTEGER NOT NULL CHECK(typeof(evidence_offset)='integer' AND evidence_offset>=29),PRIMARY KEY(source_alias,target_alias),FOREIGN KEY(source_alias,source_version_id) REFERENCES group_version_aliases(external_version,group_version_id),FOREIGN KEY(target_alias,target_version_id) REFERENCES group_version_aliases(external_version,group_version_id)) WITHOUT ROWID;
CREATE INDEX ix_compact_group_lineage_source ON group_lineage(source_version_id,target_version_id);
CREATE INDEX ix_compact_group_lineage_target ON group_lineage(target_version_id,source_version_id);
CREATE TABLE group_generation_lineage (generation_id INTEGER NOT NULL,source_alias TEXT NOT NULL,target_alias TEXT NOT NULL,PRIMARY KEY(generation_id,source_alias,target_alias),FOREIGN KEY(generation_id,target_alias) REFERENCES generation_groups(generation_id,external_version),FOREIGN KEY(source_alias,target_alias) REFERENCES group_lineage(source_alias,target_alias)) WITHOUT ROWID;
CREATE INDEX ix_group_generation_lineage_edge ON group_generation_lineage(source_alias,target_alias,generation_id);
CREATE TABLE group_lineage_retirements (source_alias TEXT NOT NULL,target_alias TEXT NOT NULL,PRIMARY KEY(source_alias,target_alias),FOREIGN KEY(source_alias,target_alias) REFERENCES group_lineage(source_alias,target_alias)) WITHOUT ROWID;
CREATE TABLE group_evidence_owners (kind TEXT NOT NULL CHECK(kind IN ('offer','response','comparison','prepared','pending','checkpoint')),external_key TEXT NOT NULL CHECK(length(external_key)>0),reference_digest TEXT NOT NULL CHECK(length(reference_digest)=64 AND reference_digest NOT GLOB '*[^0-9a-f]*'),created_at REAL NOT NULL CHECK(typeof(created_at) IN ('real','integer') AND abs(created_at)<=1.7976931348623157e308),PRIMARY KEY(kind,external_key)) WITHOUT ROWID;
CREATE TABLE group_evidence_generations (kind TEXT NOT NULL,external_key TEXT NOT NULL,generation_id INTEGER NOT NULL REFERENCES group_generations(id),PRIMARY KEY(kind,external_key,generation_id),FOREIGN KEY(kind,external_key) REFERENCES group_evidence_owners(kind,external_key)) WITHOUT ROWID;
CREATE INDEX ix_group_evidence_generation ON group_evidence_generations(generation_id,kind,external_key);
CREATE TABLE group_evidence_versions (kind TEXT NOT NULL,external_key TEXT NOT NULL,external_version TEXT NOT NULL,group_version_id INTEGER NOT NULL,PRIMARY KEY(kind,external_key,external_version),FOREIGN KEY(kind,external_key) REFERENCES group_evidence_owners(kind,external_key),FOREIGN KEY(external_version,group_version_id) REFERENCES group_version_aliases(external_version,group_version_id)) WITHOUT ROWID;
CREATE INDEX ix_group_evidence_version ON group_evidence_versions(group_version_id,kind,external_key);
CREATE TABLE unresolved_group_evidence (kind TEXT NOT NULL,external_key TEXT NOT NULL,reference_kind TEXT NOT NULL CHECK(reference_kind IN ('generation','version')),raw_key TEXT NOT NULL,reason TEXT NOT NULL CHECK(reason IN ('missing_generation','missing_version','wrong_generation','wrong_group')),PRIMARY KEY(kind,external_key,reference_kind,raw_key),FOREIGN KEY(kind,external_key) REFERENCES group_evidence_owners(kind,external_key)) WITHOUT ROWID;
