CREATE INDEX ix_group_alias_first_generation ON group_version_aliases(first_generation_id,external_version);
CREATE TABLE group_unknown (generation_id INTEGER NOT NULL REFERENCES group_generations(id),recording_id INTEGER NOT NULL REFERENCES recordings(id),reason TEXT NOT NULL,PRIMARY KEY(generation_id,recording_id)) WITHOUT ROWID;
CREATE TABLE recommendation_generations (id INTEGER PRIMARY KEY AUTOINCREMENT,external_key TEXT NOT NULL UNIQUE CHECK(length(external_key)>0),policy_version TEXT NOT NULL REFERENCES recommendation_policies(version),group_generation_id INTEGER REFERENCES group_publications(generation_id),output_digest TEXT NOT NULL CHECK(length(output_digest)=64 AND output_digest NOT GLOB '*[^0-9a-f]*'),bundle_required INTEGER NOT NULL DEFAULT 0 CHECK(typeof(bundle_required)='integer' AND bundle_required IN (0,1)),input_revision INTEGER CHECK(input_revision IS NULL OR (typeof(input_revision)='integer' AND input_revision>=0)),revision_reason TEXT CHECK(revision_reason='legacy_not_recorded'),status TEXT NOT NULL DEFAULT 'building' CHECK(status IN ('building','ready','published','retiring')),created_at REAL NOT NULL CHECK(typeof(created_at) IN ('real','integer') AND abs(created_at)<=1.7976931348623157e308),published_at REAL CHECK(published_at IS NULL OR (typeof(published_at) IN ('real','integer') AND abs(published_at)<=1.7976931348623157e308)),CHECK((input_revision IS NOT NULL AND revision_reason IS NULL) OR (input_revision IS NULL AND revision_reason IS NOT NULL)),CHECK((status IN ('building','ready') AND published_at IS NULL) OR status='retiring' OR (status='published' AND published_at IS NOT NULL)));
CREATE INDEX ix_recommendation_generation_policy ON recommendation_generations(policy_version,id);
CREATE INDEX ix_recommendation_generation_group ON recommendation_generations(group_generation_id,id) WHERE group_generation_id IS NOT NULL;
CREATE TABLE recommendation_builds (generation_id INTEGER PRIMARY KEY NOT NULL REFERENCES recommendation_generations(id),owner TEXT NOT NULL CHECK(length(owner)>0),expires_at REAL NOT NULL CHECK(typeof(expires_at) IN ('real','integer') AND abs(expires_at)<=1.7976931348623157e308),plan_digest TEXT NOT NULL CHECK(length(plan_digest)=64 AND plan_digest NOT GLOB '*[^0-9a-f]*')) WITHOUT ROWID;
CREATE INDEX ix_recommendation_build_expiry ON recommendation_builds(expires_at,generation_id);
CREATE TABLE recommendation_generation_surfaces (generation_id INTEGER NOT NULL REFERENCES recommendation_generations(id),surface TEXT NOT NULL CHECK(length(surface)>0),pool_count INTEGER NOT NULL CHECK(typeof(pool_count)='integer' AND pool_count>=0),output_count INTEGER NOT NULL CHECK(typeof(output_count)='integer' AND output_count>=0),PRIMARY KEY(generation_id,surface)) WITHOUT ROWID;
CREATE TABLE recommendation_bundle_framing (generation_id INTEGER PRIMARY KEY NOT NULL REFERENCES recommendation_generations(id),presence INTEGER NOT NULL CHECK(typeof(presence)='integer' AND presence BETWEEN 0 AND 2047),comfort_pool INTEGER CHECK(comfort_pool IS NULL OR (typeof(comfort_pool)='integer' AND comfort_pool>=0)),year_low INTEGER CHECK(year_low IS NULL OR typeof(year_low)='integer'),year_high INTEGER CHECK(year_high IS NULL OR typeof(year_high)='integer'),full_pools INTEGER CHECK(full_pools IS NULL OR (typeof(full_pools)='integer' AND full_pools IN (0,1))),unmodeled INTEGER CHECK(unmodeled IS NULL OR (typeof(unmodeled)='integer' AND unmodeled IN (0,1))),musical_generation TEXT,radio_generation TEXT,radio_space TEXT,intensity_version INTEGER CHECK(intensity_version IS NULL OR (typeof(intensity_version)='integer' AND intensity_version>=0)),radio_profile_version TEXT,vibe_version TEXT,vibe_profile_version TEXT,CHECK((year_low IS NULL AND year_high IS NULL) OR (year_low IS NOT NULL AND year_high IS NOT NULL AND year_low<=year_high))) WITHOUT ROWID;
CREATE TABLE recommendation_heads (surface TEXT PRIMARY KEY NOT NULL CHECK(length(surface)>0),generation_id INTEGER NOT NULL,FOREIGN KEY(generation_id,surface) REFERENCES recommendation_generation_surfaces(generation_id,surface)) WITHOUT ROWID;
CREATE INDEX ix_recommendation_head_generation ON recommendation_heads(generation_id,surface);
CREATE TABLE recommendation_pools (id INTEGER PRIMARY KEY AUTOINCREMENT,pool_key TEXT NOT NULL CHECK(length(pool_key)>0),policy_version TEXT NOT NULL REFERENCES recommendation_policies(version),group_version_id INTEGER REFERENCES group_versions(id),input_fingerprint TEXT NOT NULL CHECK(length(input_fingerprint)=64 AND input_fingerprint NOT GLOB '*[^0-9a-f]*'),content_digest TEXT NOT NULL UNIQUE CHECK(length(content_digest)=64 AND content_digest NOT GLOB '*[^0-9a-f]*'),purpose TEXT NOT NULL CHECK(purpose IN ('card','radio','ppr','vibe','temporal','fresh')),eligible_count INTEGER NOT NULL CHECK(typeof(eligible_count)='integer' AND eligible_count>=0),complete INTEGER NOT NULL DEFAULT 0 CHECK(typeof(complete)='integer' AND complete IN (0,1)));
CREATE INDEX ix_recommendation_pool_policy ON recommendation_pools(policy_version,id);
