CREATE TABLE recommendation_build_pools (generation_id INTEGER NOT NULL REFERENCES recommendation_builds(generation_id),pool_id INTEGER NOT NULL REFERENCES recommendation_pools(id),PRIMARY KEY(generation_id,pool_id)) WITHOUT ROWID;
CREATE TABLE recommendation_pool_retirements (pool_id INTEGER PRIMARY KEY NOT NULL REFERENCES recommendation_pools(id)) WITHOUT ROWID;
