CREATE INDEX ix_recommendation_candidate_recording ON recommendation_candidates(recording_id,pool_id);
CREATE TABLE unresolved_recommendation_candidates (pool_id INTEGER NOT NULL REFERENCES recommendation_pools(id),raw_key TEXT NOT NULL CHECK(length(raw_key)>0),rank INTEGER NOT NULL CHECK(typeof(rank)='integer' AND rank>=0),score REAL CHECK(score IS NULL OR (typeof(score) IN ('real','integer') AND abs(score)<=1.7976931348623157e308)),intensity_band INTEGER CHECK(intensity_band IS NULL OR (typeof(intensity_band)='integer' AND intensity_band BETWEEN 0 AND 50)),genre_key TEXT,reason TEXT NOT NULL CHECK(reason='missing_recording'),CHECK((intensity_band IS NULL)=(genre_key IS NULL)),PRIMARY KEY(pool_id,raw_key),UNIQUE(pool_id,rank)) WITHOUT ROWID;
CREATE TABLE recommendation_radio_bands (pool_id INTEGER NOT NULL,recording_id INTEGER NOT NULL,intensity_band INTEGER NOT NULL CHECK(typeof(intensity_band)='integer' AND intensity_band BETWEEN 0 AND 50),genre_key TEXT NOT NULL,PRIMARY KEY(pool_id,recording_id),FOREIGN KEY(pool_id,recording_id) REFERENCES recommendation_candidates(pool_id,recording_id)) WITHOUT ROWID;
CREATE INDEX ix_recommendation_radio_band ON recommendation_radio_bands(pool_id,intensity_band,genre_key,recording_id);
CREATE INDEX ix_recommendation_radio_genre ON recommendation_radio_bands(pool_id,genre_key,intensity_band,recording_id);
CREATE TABLE recommendation_surface_pools (generation_id INTEGER NOT NULL,surface TEXT NOT NULL,mode_key TEXT NOT NULL,purpose TEXT NOT NULL CHECK(length(purpose)>0),pool_id INTEGER NOT NULL REFERENCES recommendation_pools(id),PRIMARY KEY(generation_id,surface,mode_key,purpose),FOREIGN KEY(generation_id,surface) REFERENCES recommendation_generation_surfaces(generation_id,surface)) WITHOUT ROWID;
CREATE INDEX ix_recommendation_surface_pool ON recommendation_surface_pools(pool_id,generation_id);
CREATE TABLE prepared_outputs (id INTEGER PRIMARY KEY AUTOINCREMENT,generation_id INTEGER NOT NULL,surface TEXT NOT NULL,chunk_key TEXT NOT NULL,filename TEXT NOT NULL CHECK(length(filename)>0),content_digest TEXT NOT NULL CHECK(length(content_digest)=64 AND content_digest NOT GLOB '*[^0-9a-f]*'),byte_size INTEGER NOT NULL CHECK(typeof(byte_size)='integer' AND byte_size BETWEEN 1 AND 1048576),format_version INTEGER NOT NULL CHECK(typeof(format_version)='integer' AND format_version=1),built_at REAL NOT NULL CHECK(typeof(built_at) IN ('real','integer') AND abs(built_at)<=1.7976931348623157e308),expires_at REAL CHECK(expires_at IS NULL OR (typeof(expires_at) IN ('real','integer') AND abs(expires_at)<=1.7976931348623157e308)),pool_id INTEGER REFERENCES recommendation_pools(id),first_rank INTEGER CHECK(first_rank IS NULL OR (typeof(first_rank)='integer' AND first_rank>=0)),last_rank INTEGER CHECK(last_rank IS NULL OR (typeof(last_rank)='integer' AND last_rank>=first_rank)),CHECK((pool_id IS NULL AND first_rank IS NULL AND last_rank IS NULL) OR (pool_id IS NOT NULL AND first_rank IS NOT NULL AND last_rank IS NOT NULL)),UNIQUE(generation_id,surface,chunk_key),FOREIGN KEY(generation_id,surface) REFERENCES recommendation_generation_surfaces(generation_id,surface));
CREATE INDEX ix_prepared_output_expiry ON prepared_outputs(expires_at,id) WHERE expires_at IS NOT NULL;
CREATE UNIQUE INDEX ix_prepared_output_pool_rank ON prepared_outputs(generation_id,surface,pool_id,first_rank) WHERE pool_id IS NOT NULL;
CREATE INDEX ix_prepared_output_pool ON prepared_outputs(pool_id,id) WHERE pool_id IS NOT NULL;
CREATE TRIGGER selected_prepared_output_pool BEFORE INSERT ON prepared_outputs WHEN NEW.pool_id IS NOT NULL AND (NOT EXISTS(SELECT 1 FROM recommendation_surface_pools m JOIN recommendation_pools p ON p.id=m.pool_id WHERE m.generation_id=NEW.generation_id AND m.surface=NEW.surface AND m.pool_id=NEW.pool_id AND NEW.last_rank<p.eligible_count) OR EXISTS(SELECT 1 FROM prepared_outputs o WHERE o.generation_id=NEW.generation_id AND o.surface=NEW.surface AND o.pool_id=NEW.pool_id AND o.first_rank<=NEW.last_rank AND o.last_rank>=NEW.first_rank)) BEGIN SELECT RAISE(ABORT,'Display chunk requires disjoint ranks from a selected pool'); END;
CREATE TABLE recommendation_generation_refs (kind TEXT NOT NULL CHECK(kind IN ('offer','response','prepared','comparison','pending','checkpoint')),external_key TEXT NOT NULL CHECK(length(external_key)>0),generation_id INTEGER NOT NULL REFERENCES recommendation_generations(id),PRIMARY KEY(kind,external_key,generation_id)) WITHOUT ROWID;
CREATE INDEX ix_recommendation_generation_ref ON recommendation_generation_refs(generation_id,kind,external_key);
CREATE TRIGGER retired_proposal_recommendation_references BEFORE DELETE ON rec_proposals BEGIN DELETE FROM recommendation_generation_refs WHERE kind IN ('prepared','comparison') AND external_key IN ('proposal:'||OLD.surface||':context','proposal:'||OLD.surface||':choice_context','proposal:'||OLD.surface||':album_choice_context','proposal:'||OLD.surface||':recommendations'); END;
CREATE TRIGGER immutable_recommendation_generation BEFORE UPDATE OF id,external_key,policy_version,group_generation_id,output_digest,bundle_required,input_revision,revision_reason,created_at ON recommendation_generations BEGIN SELECT RAISE(ABORT,'Recommendation generation inputs are immutable'); END;
CREATE TRIGGER new_recommendation_generation BEFORE INSERT ON recommendation_generations WHEN NEW.status<>'building' BEGIN SELECT RAISE(ABORT,'Recommendation publication must be built privately'); END;
CREATE TRIGGER recommendation_generation_transition BEFORE UPDATE OF status,published_at ON recommendation_generations WHEN NOT ((OLD.status='building' AND NEW.status='ready' AND NEW.published_at IS NULL) OR (OLD.status='ready' AND NEW.status='published' AND NEW.published_at IS NOT NULL) OR (OLD.status IN ('building','ready','published') AND NEW.status='retiring' AND NEW.published_at IS OLD.published_at AND NOT EXISTS(SELECT 1 FROM recommendation_heads WHERE generation_id=OLD.id) AND NOT EXISTS(SELECT 1 FROM recommendation_generation_refs WHERE generation_id=OLD.id))) BEGIN SELECT RAISE(ABORT,'Invalid recommendation publication transition'); END;
CREATE TRIGGER complete_recommendation_generation BEFORE UPDATE OF status ON recommendation_generations WHEN NEW.status='ready' AND (NOT EXISTS(SELECT 1 FROM recommendation_generation_surfaces WHERE generation_id=OLD.id) OR (OLD.bundle_required=1 AND NOT EXISTS(SELECT 1 FROM recommendation_bundle_framing WHERE generation_id=OLD.id)) OR EXISTS(SELECT 1 FROM recommendation_generation_surfaces s WHERE s.generation_id=OLD.id AND (s.pool_count<>(SELECT count(*) FROM recommendation_surface_pools m WHERE m.generation_id=s.generation_id AND m.surface=s.surface) OR s.output_count<>(SELECT count(*) FROM prepared_outputs o WHERE o.generation_id=s.generation_id AND o.surface=s.surface)))) BEGIN SELECT RAISE(ABORT,'Recommendation publication is incomplete'); END;
CREATE TRIGGER published_recommendation_head_insert BEFORE INSERT ON recommendation_heads WHEN NOT EXISTS(SELECT 1 FROM recommendation_generations WHERE id=NEW.generation_id AND status='published') BEGIN SELECT RAISE(ABORT,'Recommendation head requires published output'); END;
CREATE TRIGGER published_recommendation_head_update BEFORE UPDATE ON recommendation_heads WHEN NOT EXISTS(SELECT 1 FROM recommendation_generations WHERE id=NEW.generation_id AND status='published') BEGIN SELECT RAISE(ABORT,'Recommendation head requires published output'); END;
CREATE TRIGGER retained_recommendation_generation BEFORE DELETE ON recommendation_generations WHEN OLD.status<>'retiring' BEGIN SELECT RAISE(ABORT,'Recommendation retirement must be fenced'); END;
CREATE TRIGGER frozen_recommendation_generation_surfaces_insert BEFORE INSERT ON recommendation_generation_surfaces WHEN EXISTS(SELECT 1 FROM recommendation_generations WHERE id=NEW.generation_id AND status NOT IN ('building')) BEGIN SELECT RAISE(ABORT,'Recommendation publication content is immutable'); END;
CREATE TRIGGER frozen_recommendation_generation_surfaces_update BEFORE UPDATE ON recommendation_generation_surfaces WHEN EXISTS(SELECT 1 FROM recommendation_generations WHERE id=OLD.generation_id AND status NOT IN ('building')) OR EXISTS(SELECT 1 FROM recommendation_generations WHERE id=NEW.generation_id AND status NOT IN ('building')) BEGIN SELECT RAISE(ABORT,'Recommendation publication content is immutable'); END;
CREATE TRIGGER frozen_recommendation_generation_surfaces_delete BEFORE DELETE ON recommendation_generation_surfaces WHEN EXISTS(SELECT 1 FROM recommendation_generations WHERE id=OLD.generation_id AND status NOT IN ('building','retiring')) BEGIN SELECT RAISE(ABORT,'Recommendation publication content is immutable'); END;
CREATE TRIGGER frozen_recommendation_surface_pools_insert BEFORE INSERT ON recommendation_surface_pools WHEN EXISTS(SELECT 1 FROM recommendation_generations WHERE id=NEW.generation_id AND status NOT IN ('building')) BEGIN SELECT RAISE(ABORT,'Recommendation publication content is immutable'); END;
CREATE TRIGGER frozen_recommendation_surface_pools_update BEFORE UPDATE ON recommendation_surface_pools WHEN EXISTS(SELECT 1 FROM recommendation_generations WHERE id=OLD.generation_id AND status NOT IN ('building')) OR EXISTS(SELECT 1 FROM recommendation_generations WHERE id=NEW.generation_id AND status NOT IN ('building')) BEGIN SELECT RAISE(ABORT,'Recommendation publication content is immutable'); END;
CREATE TRIGGER frozen_recommendation_surface_pools_delete BEFORE DELETE ON recommendation_surface_pools WHEN EXISTS(SELECT 1 FROM recommendation_generations WHERE id=OLD.generation_id AND status NOT IN ('building','retiring')) BEGIN SELECT RAISE(ABORT,'Recommendation publication content is immutable'); END;
CREATE TRIGGER frozen_recommendation_bundle_framing_insert BEFORE INSERT ON recommendation_bundle_framing WHEN EXISTS(SELECT 1 FROM recommendation_generations WHERE id=NEW.generation_id AND status NOT IN ('building')) BEGIN SELECT RAISE(ABORT,'Recommendation publication content is immutable'); END;
CREATE TRIGGER frozen_recommendation_bundle_framing_update BEFORE UPDATE ON recommendation_bundle_framing WHEN EXISTS(SELECT 1 FROM recommendation_generations WHERE id=OLD.generation_id AND status NOT IN ('building')) OR EXISTS(SELECT 1 FROM recommendation_generations WHERE id=NEW.generation_id AND status NOT IN ('building')) BEGIN SELECT RAISE(ABORT,'Recommendation publication content is immutable'); END;
CREATE TRIGGER frozen_recommendation_bundle_framing_delete BEFORE DELETE ON recommendation_bundle_framing WHEN EXISTS(SELECT 1 FROM recommendation_generations WHERE id=OLD.generation_id AND status NOT IN ('building','retiring')) BEGIN SELECT RAISE(ABORT,'Recommendation publication content is immutable'); END;
CREATE TRIGGER frozen_prepared_outputs_insert BEFORE INSERT ON prepared_outputs WHEN EXISTS(SELECT 1 FROM recommendation_generations WHERE id=NEW.generation_id AND status NOT IN ('building')) BEGIN SELECT RAISE(ABORT,'Recommendation publication content is immutable'); END;
CREATE TRIGGER frozen_prepared_outputs_update BEFORE UPDATE ON prepared_outputs WHEN (EXISTS(SELECT 1 FROM recommendation_generations WHERE id=OLD.generation_id AND status NOT IN ('building')) OR EXISTS(SELECT 1 FROM recommendation_generations WHERE id=NEW.generation_id AND status NOT IN ('building'))) AND (NEW.id IS NOT OLD.id OR NEW.generation_id IS NOT OLD.generation_id OR NEW.surface IS NOT OLD.surface OR NEW.chunk_key IS NOT OLD.chunk_key OR NEW.content_digest IS NOT OLD.content_digest OR NEW.byte_size IS NOT OLD.byte_size OR NEW.format_version IS NOT OLD.format_version OR NEW.built_at IS NOT OLD.built_at OR NEW.expires_at IS NOT OLD.expires_at OR NEW.pool_id IS NOT OLD.pool_id OR NEW.first_rank IS NOT OLD.first_rank OR NEW.last_rank IS NOT OLD.last_rank) BEGIN SELECT RAISE(ABORT,'Recommendation publication content is immutable'); END;
CREATE TRIGGER frozen_prepared_outputs_delete BEFORE DELETE ON prepared_outputs WHEN EXISTS(SELECT 1 FROM recommendation_generations WHERE id=OLD.generation_id AND status NOT IN ('building','retiring')) BEGIN SELECT RAISE(ABORT,'Recommendation publication content is immutable'); END;
CREATE TRIGGER immutable_recommendation_pool BEFORE UPDATE OF id,pool_key,policy_version,group_version_id,input_fingerprint,content_digest,purpose,eligible_count ON recommendation_pools BEGIN SELECT RAISE(ABORT,'Recommendation pool content is immutable'); END;
CREATE TRIGGER new_recommendation_pool BEFORE INSERT ON recommendation_pools WHEN NEW.complete<>0 BEGIN SELECT RAISE(ABORT,'Recommendation pool must be built privately'); END;
CREATE TRIGGER complete_recommendation_pool BEFORE UPDATE OF complete ON recommendation_pools WHEN OLD.complete=1 OR NEW.complete<>1 OR NEW.eligible_count<>(SELECT count(*) FROM recommendation_candidates WHERE pool_id=OLD.id)+(SELECT count(*) FROM unresolved_recommendation_candidates WHERE pool_id=OLD.id) OR (NEW.eligible_count>0 AND ((SELECT min(rank) FROM (SELECT rank FROM recommendation_candidates WHERE pool_id=OLD.id UNION ALL SELECT rank FROM unresolved_recommendation_candidates WHERE pool_id=OLD.id))<>0 OR (SELECT max(rank) FROM (SELECT rank FROM recommendation_candidates WHERE pool_id=OLD.id UNION ALL SELECT rank FROM unresolved_recommendation_candidates WHERE pool_id=OLD.id))<>NEW.eligible_count-1)) BEGIN SELECT RAISE(ABORT,'Recommendation pool membership is incomplete or sealed'); END;
CREATE TRIGGER frozen_recommendation_candidates_insert BEFORE INSERT ON recommendation_candidates WHEN EXISTS(SELECT 1 FROM recommendation_pools p WHERE p.id=NEW.pool_id AND p.complete=1) BEGIN SELECT RAISE(ABORT,'Recommendation candidate content is immutable'); END;
CREATE TRIGGER frozen_recommendation_candidates_update BEFORE UPDATE ON recommendation_candidates WHEN EXISTS(SELECT 1 FROM recommendation_pools p WHERE p.id=OLD.pool_id AND p.complete=1) OR EXISTS(SELECT 1 FROM recommendation_pools p WHERE p.id=NEW.pool_id AND p.complete=1) BEGIN SELECT RAISE(ABORT,'Recommendation candidate content is immutable'); END;
CREATE TRIGGER frozen_recommendation_candidates_delete BEFORE DELETE ON recommendation_candidates WHEN EXISTS(SELECT 1 FROM recommendation_pools p WHERE p.id=OLD.pool_id AND p.complete=1 AND (EXISTS(SELECT 1 FROM recommendation_surface_pools m WHERE m.pool_id=p.id) OR EXISTS(SELECT 1 FROM recommendation_build_pools b WHERE b.pool_id=p.id))) BEGIN SELECT RAISE(ABORT,'Recommendation candidate content is immutable'); END;
CREATE TRIGGER frozen_unresolved_recommendation_candidates_insert BEFORE INSERT ON unresolved_recommendation_candidates WHEN EXISTS(SELECT 1 FROM recommendation_pools p WHERE p.id=NEW.pool_id AND p.complete=1) BEGIN SELECT RAISE(ABORT,'Recommendation candidate content is immutable'); END;
CREATE TRIGGER frozen_unresolved_recommendation_candidates_update BEFORE UPDATE ON unresolved_recommendation_candidates WHEN EXISTS(SELECT 1 FROM recommendation_pools p WHERE p.id=OLD.pool_id AND p.complete=1) OR EXISTS(SELECT 1 FROM recommendation_pools p WHERE p.id=NEW.pool_id AND p.complete=1) BEGIN SELECT RAISE(ABORT,'Recommendation candidate content is immutable'); END;
CREATE TRIGGER frozen_unresolved_recommendation_candidates_delete BEFORE DELETE ON unresolved_recommendation_candidates WHEN EXISTS(SELECT 1 FROM recommendation_pools p WHERE p.id=OLD.pool_id AND p.complete=1 AND (EXISTS(SELECT 1 FROM recommendation_surface_pools m WHERE m.pool_id=p.id) OR EXISTS(SELECT 1 FROM recommendation_build_pools b WHERE b.pool_id=p.id))) BEGIN SELECT RAISE(ABORT,'Recommendation candidate content is immutable'); END;
CREATE TRIGGER frozen_recommendation_radio_bands_insert BEFORE INSERT ON recommendation_radio_bands WHEN EXISTS(SELECT 1 FROM recommendation_pools p WHERE p.id=NEW.pool_id AND p.complete=1) BEGIN SELECT RAISE(ABORT,'Recommendation candidate content is immutable'); END;
CREATE TRIGGER frozen_recommendation_radio_bands_update BEFORE UPDATE ON recommendation_radio_bands WHEN EXISTS(SELECT 1 FROM recommendation_pools p WHERE p.id=OLD.pool_id AND p.complete=1) OR EXISTS(SELECT 1 FROM recommendation_pools p WHERE p.id=NEW.pool_id AND p.complete=1) BEGIN SELECT RAISE(ABORT,'Recommendation candidate content is immutable'); END;
CREATE TRIGGER frozen_recommendation_radio_bands_delete BEFORE DELETE ON recommendation_radio_bands WHEN EXISTS(SELECT 1 FROM recommendation_pools p WHERE p.id=OLD.pool_id AND p.complete=1 AND (EXISTS(SELECT 1 FROM recommendation_surface_pools m WHERE m.pool_id=p.id) OR EXISTS(SELECT 1 FROM recommendation_build_pools b WHERE b.pool_id=p.id))) BEGIN SELECT RAISE(ABORT,'Recommendation candidate content is immutable'); END;
CREATE TRIGGER complete_recommendation_pool_selection BEFORE INSERT ON recommendation_surface_pools WHEN EXISTS(SELECT 1 FROM recommendation_pool_retirements WHERE pool_id=NEW.pool_id) OR NOT EXISTS(SELECT 1 FROM recommendation_pools p JOIN recommendation_generations g ON g.id=NEW.generation_id JOIN recommendation_policies pp ON pp.version=p.policy_version JOIN recommendation_policies gp ON gp.version=g.policy_version WHERE p.id=NEW.pool_id AND p.complete=1 AND COALESCE(pp.base_version,pp.version)=COALESCE(gp.base_version,gp.version) AND (p.group_version_id IS NULL OR EXISTS(SELECT 1 FROM generation_groups x WHERE x.generation_id=g.group_generation_id AND x.group_version_id=p.group_version_id))) BEGIN SELECT RAISE(ABORT,'Recommendation pool has incompatible publication inputs'); END;
CREATE TRIGGER immutable_recommendation_pool_selection BEFORE UPDATE ON recommendation_surface_pools BEGIN SELECT RAISE(ABORT,'Recommendation pool selection is immutable'); END;
CREATE TRIGGER immutable_recommendation_generation_ref BEFORE UPDATE ON recommendation_generation_refs BEGIN SELECT RAISE(ABORT,'Recommendation generation references are immutable'); END;
CREATE TRIGGER live_recommendation_generation_ref BEFORE INSERT ON recommendation_generation_refs WHEN NOT EXISTS(SELECT 1 FROM recommendation_generations WHERE id=NEW.generation_id AND status='published') BEGIN SELECT RAISE(ABORT,'Recommendation evidence requires a published generation'); END;
CREATE TRIGGER retained_recommendation_group BEFORE DELETE ON group_publications WHEN EXISTS(SELECT 1 FROM recommendation_generations WHERE group_generation_id=OLD.generation_id) BEGIN SELECT RAISE(ABORT,'Recommendation publication retains its musical groups'); END;
CREATE TRIGGER retained_recommendation_pool BEFORE INSERT ON recommendation_pool_retirements WHEN EXISTS(SELECT 1 FROM recommendation_surface_pools WHERE pool_id=NEW.pool_id) OR EXISTS(SELECT 1 FROM recommendation_build_pools WHERE pool_id=NEW.pool_id) OR EXISTS(SELECT 1 FROM prepared_outputs WHERE pool_id=NEW.pool_id) BEGIN SELECT RAISE(ABORT,'Recommendation pool still has an owner'); END;
CREATE TRIGGER live_recommendation_build_pool BEFORE INSERT ON recommendation_build_pools WHEN EXISTS(SELECT 1 FROM recommendation_pool_retirements WHERE pool_id=NEW.pool_id) BEGIN SELECT RAISE(ABORT,'Recommendation pool is being retired'); END;
CREATE TRIGGER private_recommendation_build_pool BEFORE INSERT ON recommendation_build_pools WHEN EXISTS(SELECT 1 FROM recommendation_pools p WHERE p.id=NEW.pool_id AND p.complete=0 AND EXISTS(SELECT 1 FROM recommendation_build_pools b WHERE b.pool_id=p.id AND b.generation_id<>NEW.generation_id)) BEGIN SELECT RAISE(ABORT,'Recommendation pool is leased by another build'); END;
CREATE TRIGGER recommendation_radio_band_owner BEFORE INSERT ON recommendation_radio_bands WHEN NOT EXISTS(SELECT 1 FROM recommendation_pools WHERE id=NEW.pool_id AND purpose='radio') BEGIN SELECT RAISE(ABORT,'Radio bands require a radio pool'); END;
CREATE TRIGGER unresolved_recommendation_radio_band_owner BEFORE INSERT ON unresolved_recommendation_candidates WHEN NEW.intensity_band IS NOT NULL AND NOT EXISTS(SELECT 1 FROM recommendation_pools WHERE id=NEW.pool_id AND purpose='radio') BEGIN SELECT RAISE(ABORT,'Radio bands require a radio pool'); END;
CREATE TRIGGER distinct_recommendation_candidates_rank_insert BEFORE INSERT ON recommendation_candidates WHEN EXISTS(SELECT 1 FROM unresolved_recommendation_candidates WHERE pool_id=NEW.pool_id AND rank=NEW.rank) BEGIN SELECT RAISE(ABORT,'Recommendation pool ranks must be unique'); END;
CREATE TRIGGER distinct_recommendation_candidates_rank_update BEFORE UPDATE ON recommendation_candidates WHEN EXISTS(SELECT 1 FROM unresolved_recommendation_candidates WHERE pool_id=NEW.pool_id AND rank=NEW.rank) BEGIN SELECT RAISE(ABORT,'Recommendation pool ranks must be unique'); END;
CREATE TRIGGER distinct_unresolved_recommendation_candidates_rank_insert BEFORE INSERT ON unresolved_recommendation_candidates WHEN EXISTS(SELECT 1 FROM recommendation_candidates WHERE pool_id=NEW.pool_id AND rank=NEW.rank) BEGIN SELECT RAISE(ABORT,'Recommendation pool ranks must be unique'); END;
CREATE TRIGGER distinct_unresolved_recommendation_candidates_rank_update BEFORE UPDATE ON unresolved_recommendation_candidates WHEN EXISTS(SELECT 1 FROM recommendation_candidates WHERE pool_id=NEW.pool_id AND rank=NEW.rank) BEGIN SELECT RAISE(ABORT,'Recommendation pool ranks must be unique'); END;
CREATE TABLE unresolved_group_unknown (generation_id INTEGER NOT NULL REFERENCES group_generations(id),raw_key TEXT NOT NULL,reason TEXT NOT NULL,resolution_reason TEXT NOT NULL CHECK(resolution_reason='missing_recording'),PRIMARY KEY(generation_id,raw_key)) WITHOUT ROWID;
CREATE TABLE group_graph (generation_id INTEGER NOT NULL REFERENCES group_generations(id),left_recording_id INTEGER NOT NULL REFERENCES recordings(id),right_recording_id INTEGER NOT NULL REFERENCES recordings(id),weight REAL NOT NULL CHECK(weight BETWEEN 0 AND 1),support REAL NOT NULL CHECK(support BETWEEN 0 AND 1),PRIMARY KEY(generation_id,left_recording_id,right_recording_id)) WITHOUT ROWID;
CREATE TABLE unresolved_group_graph (generation_id INTEGER NOT NULL REFERENCES group_generations(id),left_key TEXT NOT NULL,right_key TEXT NOT NULL,weight REAL NOT NULL CHECK(weight BETWEEN 0 AND 1),support REAL NOT NULL CHECK(support BETWEEN 0 AND 1),reason TEXT NOT NULL CHECK(reason='missing_recording'),PRIMARY KEY(generation_id,left_key,right_key)) WITHOUT ROWID;
CREATE TABLE group_assignments (generation_id INTEGER NOT NULL REFERENCES group_generations(id),recording_id INTEGER NOT NULL REFERENCES recordings(id),group_version_id INTEGER,similarity REAL NOT NULL CHECK(similarity BETWEEN 0 AND 1),support REAL NOT NULL CHECK(support BETWEEN 0 AND 1),profile_digest TEXT,prepared_at REAL NOT NULL CHECK(typeof(prepared_at) IN ('real','integer') AND abs(prepared_at)<=1.7976931348623157e308),PRIMARY KEY(generation_id,recording_id),FOREIGN KEY(generation_id,group_version_id) REFERENCES generation_groups(generation_id,group_version_id)) WITHOUT ROWID;
CREATE TABLE unresolved_group_assignments (generation_id INTEGER NOT NULL REFERENCES group_generations(id),raw_key TEXT NOT NULL,group_version_id INTEGER,similarity REAL NOT NULL CHECK(similarity BETWEEN 0 AND 1),support REAL NOT NULL CHECK(support BETWEEN 0 AND 1),profile_digest TEXT,prepared_at REAL NOT NULL CHECK(typeof(prepared_at) IN ('real','integer') AND abs(prepared_at)<=1.7976931348623157e308),resolution_reason TEXT NOT NULL DEFAULT 'missing_recording' CHECK(resolution_reason='missing_recording'),PRIMARY KEY(generation_id,raw_key),FOREIGN KEY(generation_id,group_version_id) REFERENCES generation_groups(generation_id,group_version_id)) WITHOUT ROWID;
CREATE TRIGGER immutable_group_versions BEFORE UPDATE OF id,group_id,parent_group_id,content_digest,policy_version,created_at,definition_digest,definition_bytes,leaf,legacy,membership_known,depth,size ON group_versions BEGIN SELECT RAISE(ABORT,'Musical group content is immutable'); END;
CREATE TRIGGER immutable_group_members BEFORE UPDATE ON group_members BEGIN SELECT RAISE(ABORT,'Musical group content is immutable'); END;
CREATE TRIGGER immutable_unresolved_group_members BEFORE UPDATE ON unresolved_group_members BEGIN SELECT RAISE(ABORT,'Musical group content is immutable'); END;
CREATE TRIGGER immutable_group_input_manifests BEFORE UPDATE OF id,content_digest ON group_input_manifests BEGIN SELECT RAISE(ABORT,'Musical group content is immutable'); END;
CREATE TRIGGER immutable_group_recording_inputs BEFORE UPDATE ON group_recording_inputs BEGIN SELECT RAISE(ABORT,'Musical group content is immutable'); END;
CREATE TRIGGER immutable_group_manifest_inputs BEFORE UPDATE ON group_manifest_inputs BEGIN SELECT RAISE(ABORT,'Musical group content is immutable'); END;
CREATE TRIGGER immutable_unresolved_group_manifest_inputs BEFORE UPDATE ON unresolved_group_manifest_inputs BEGIN SELECT RAISE(ABORT,'Musical group content is immutable'); END;
CREATE TRIGGER immutable_group_version_aliases BEFORE UPDATE ON group_version_aliases BEGIN SELECT RAISE(ABORT,'Musical group content is immutable'); END;
CREATE TRIGGER immutable_group_representatives BEFORE UPDATE ON group_representatives BEGIN SELECT RAISE(ABORT,'Musical group content is immutable'); END;
CREATE TRIGGER immutable_group_lineage BEFORE UPDATE OF source_alias,target_alias,source_version_id,target_version_id,relation,compatible,old_share,new_share,overlap,evidence_digest,evidence_bytes ON group_lineage BEGIN SELECT RAISE(ABORT,'Musical group content is immutable'); END;
CREATE TRIGGER complete_group_version_alias BEFORE INSERT ON group_version_aliases WHEN NOT EXISTS(SELECT 1 FROM group_version_aliases WHERE external_version=NEW.external_version) AND EXISTS(SELECT 1 FROM group_versions v JOIN group_generations g ON g.id=NEW.first_generation_id JOIN group_input_manifests i ON i.id=g.input_manifest_id WHERE v.id=NEW.group_version_id AND (i.complete=0 OR (v.membership_known=1 AND v.size<>(SELECT count(*) FROM group_members WHERE group_version_id=v.id)+(SELECT count(*) FROM unresolved_group_members WHERE group_version_id=v.id)) OR (v.membership_known=0 AND (EXISTS(SELECT 1 FROM group_members WHERE group_version_id=v.id) OR EXISTS(SELECT 1 FROM unresolved_group_members WHERE group_version_id=v.id))))) BEGIN SELECT RAISE(ABORT,'Musical group version has incomplete membership'); END;
CREATE TRIGGER sealed_group_members_insert BEFORE INSERT ON group_members WHEN EXISTS(SELECT 1 FROM group_version_aliases WHERE group_version_id=NEW.group_version_id) BEGIN SELECT RAISE(ABORT,'Musical group version is sealed'); END;
CREATE TRIGGER sealed_group_members_delete BEFORE DELETE ON group_members WHEN EXISTS(SELECT 1 FROM group_version_aliases WHERE group_version_id=OLD.group_version_id) BEGIN SELECT RAISE(ABORT,'Musical group version is sealed'); END;
CREATE TRIGGER sealed_unresolved_group_members_insert BEFORE INSERT ON unresolved_group_members WHEN EXISTS(SELECT 1 FROM group_version_aliases WHERE group_version_id=NEW.group_version_id) BEGIN SELECT RAISE(ABORT,'Musical group version is sealed'); END;
CREATE TRIGGER sealed_unresolved_group_members_delete BEFORE DELETE ON unresolved_group_members WHEN EXISTS(SELECT 1 FROM group_version_aliases WHERE group_version_id=OLD.group_version_id) BEGIN SELECT RAISE(ABORT,'Musical group version is sealed'); END;
CREATE TRIGGER sealed_group_representatives_insert BEFORE INSERT ON group_representatives WHEN EXISTS(SELECT 1 FROM group_version_aliases WHERE group_version_id=NEW.group_version_id) BEGIN SELECT RAISE(ABORT,'Musical group version is sealed'); END;
CREATE TRIGGER sealed_group_representatives_delete BEFORE DELETE ON group_representatives WHEN EXISTS(SELECT 1 FROM group_version_aliases WHERE group_version_id=OLD.group_version_id) BEGIN SELECT RAISE(ABORT,'Musical group version is sealed'); END;
CREATE TRIGGER sealed_group_manifest_inputs_insert BEFORE INSERT ON group_manifest_inputs WHEN EXISTS(SELECT 1 FROM group_input_manifests WHERE id=NEW.manifest_id AND complete=1) AND EXISTS(SELECT 1 FROM group_generations WHERE input_manifest_id=NEW.manifest_id) BEGIN SELECT RAISE(ABORT,'Musical group input manifest is sealed'); END;
CREATE TRIGGER sealed_group_manifest_inputs_delete BEFORE DELETE ON group_manifest_inputs WHEN EXISTS(SELECT 1 FROM group_input_manifests WHERE id=OLD.manifest_id AND complete=1) AND EXISTS(SELECT 1 FROM group_generations WHERE input_manifest_id=OLD.manifest_id) BEGIN SELECT RAISE(ABORT,'Musical group input manifest is sealed'); END;
CREATE TRIGGER sealed_unresolved_group_manifest_inputs_insert BEFORE INSERT ON unresolved_group_manifest_inputs WHEN EXISTS(SELECT 1 FROM group_input_manifests WHERE id=NEW.manifest_id AND complete=1) AND EXISTS(SELECT 1 FROM group_generations WHERE input_manifest_id=NEW.manifest_id) BEGIN SELECT RAISE(ABORT,'Musical group input manifest is sealed'); END;
CREATE TRIGGER sealed_unresolved_group_manifest_inputs_delete BEFORE DELETE ON unresolved_group_manifest_inputs WHEN EXISTS(SELECT 1 FROM group_input_manifests WHERE id=OLD.manifest_id AND complete=1) AND EXISTS(SELECT 1 FROM group_generations WHERE input_manifest_id=OLD.manifest_id) BEGIN SELECT RAISE(ABORT,'Musical group input manifest is sealed'); END;
CREATE TRIGGER sealed_group_input_manifest BEFORE UPDATE OF complete ON group_input_manifests WHEN OLD.complete=1 BEGIN SELECT RAISE(ABORT,'Musical group input manifest is sealed'); END;
CREATE TRIGGER published_generation_groups_insert BEFORE INSERT ON generation_groups WHEN EXISTS(SELECT 1 FROM group_publications WHERE generation_id=NEW.generation_id) BEGIN SELECT RAISE(ABORT,'Published musical group selection is immutable'); END;
CREATE TRIGGER published_generation_groups_update BEFORE UPDATE ON generation_groups WHEN EXISTS(SELECT 1 FROM group_publications WHERE generation_id=OLD.generation_id) OR EXISTS(SELECT 1 FROM group_publications WHERE generation_id=NEW.generation_id) BEGIN SELECT RAISE(ABORT,'Published musical group selection is immutable'); END;
CREATE TRIGGER published_generation_groups_delete BEFORE DELETE ON generation_groups WHEN EXISTS(SELECT 1 FROM group_publications WHERE generation_id=OLD.generation_id) BEGIN SELECT RAISE(ABORT,'Published musical group selection is immutable'); END;
CREATE TRIGGER published_group_generation_lineage_insert BEFORE INSERT ON group_generation_lineage WHEN EXISTS(SELECT 1 FROM group_publications WHERE generation_id=NEW.generation_id) BEGIN SELECT RAISE(ABORT,'Published musical group selection is immutable'); END;
CREATE TRIGGER published_group_generation_lineage_update BEFORE UPDATE ON group_generation_lineage WHEN EXISTS(SELECT 1 FROM group_publications WHERE generation_id=OLD.generation_id) OR EXISTS(SELECT 1 FROM group_publications WHERE generation_id=NEW.generation_id) BEGIN SELECT RAISE(ABORT,'Published musical group selection is immutable'); END;
CREATE TRIGGER published_group_generation_lineage_delete BEFORE DELETE ON group_generation_lineage WHEN (EXISTS(SELECT 1 FROM group_publications WHERE generation_id=OLD.generation_id)) AND NOT EXISTS(SELECT 1 FROM group_lineage_retirements WHERE source_alias=OLD.source_alias AND target_alias=OLD.target_alias) BEGIN SELECT RAISE(ABORT,'Published musical group selection is immutable'); END;
CREATE TRIGGER complete_group_publication BEFORE INSERT ON group_publications WHEN EXISTS(SELECT 1 FROM group_generations g JOIN group_input_manifests i ON i.id=g.input_manifest_id WHERE g.id=NEW.generation_id AND i.complete=0) OR EXISTS(SELECT 1 FROM group_builds WHERE generation_id=NEW.generation_id AND ready=0) OR EXISTS(SELECT 1 FROM group_build_versions WHERE generation_id=NEW.generation_id) BEGIN SELECT RAISE(ABORT,'Musical group publication is incomplete'); END;
CREATE TRIGGER immutable_group_generation BEFORE UPDATE OF id,external_key,policy_version,input_fingerprint,input_manifest_id,input_serial,created_at,metadata_digest,metadata_bytes ON group_generations BEGIN SELECT RAISE(ABORT,'Musical group generation is immutable'); END;
CREATE TRIGGER retained_group_publication_update BEFORE UPDATE ON group_publications BEGIN SELECT RAISE(ABORT,'Retained musical group publication is immutable'); END;
CREATE TRIGGER fenced_group_lineage_retirement BEFORE INSERT ON group_lineage_retirements WHEN NOT EXISTS(SELECT 1 FROM group_retention_state WHERE id=1 AND roots_complete=1) BEGIN SELECT RAISE(ABORT,'Musical group evidence backfill is incomplete'); END;
CREATE TRIGGER retained_group_publication_delete BEFORE DELETE ON group_publications WHEN NOT EXISTS(SELECT 1 FROM group_retention_state WHERE id=1 AND roots_complete=1) OR NOT EXISTS(SELECT 1 FROM group_builds WHERE generation_id=OLD.generation_id AND owner='cleanup') OR EXISTS(SELECT 1 FROM group_head WHERE generation_id=OLD.generation_id) OR EXISTS(SELECT 1 FROM group_builds WHERE parent_generation_id=OLD.generation_id) OR EXISTS(SELECT 1 FROM group_evidence_generations WHERE generation_id=OLD.generation_id) OR EXISTS(SELECT 1 FROM group_evidence_versions e JOIN group_version_aliases a ON a.external_version=e.external_version WHERE a.first_generation_id=OLD.generation_id) BEGIN SELECT RAISE(ABORT,'Retained musical group publication is immutable'); END;
CREATE TRIGGER immutable_group_evidence_owners BEFORE UPDATE ON group_evidence_owners BEGIN SELECT RAISE(ABORT,'Musical group evidence references are immutable'); END;
CREATE TRIGGER immutable_group_evidence_generations BEFORE UPDATE ON group_evidence_generations BEGIN SELECT RAISE(ABORT,'Musical group evidence references are immutable'); END;
CREATE TRIGGER immutable_group_evidence_versions BEFORE UPDATE ON group_evidence_versions BEGIN SELECT RAISE(ABORT,'Musical group evidence references are immutable'); END;
CREATE TRIGGER immutable_unresolved_group_evidence BEFORE UPDATE ON unresolved_group_evidence BEGIN SELECT RAISE(ABORT,'Musical group evidence references are immutable'); END;
CREATE TRIGGER immutable_unresolved_group_contexts BEFORE UPDATE ON unresolved_group_contexts BEGIN SELECT RAISE(ABORT,'Musical group evidence references are immutable'); END;
CREATE TRIGGER retired_proposal_group_references BEFORE DELETE ON rec_proposals BEGIN DELETE FROM group_evidence_versions WHERE kind IN ('prepared','comparison') AND external_key IN ('proposal:'||OLD.surface||':context','proposal:'||OLD.surface||':choice_context','proposal:'||OLD.surface||':album_choice_context'); DELETE FROM group_evidence_generations WHERE kind IN ('prepared','comparison') AND external_key IN ('proposal:'||OLD.surface||':context','proposal:'||OLD.surface||':choice_context','proposal:'||OLD.surface||':album_choice_context'); DELETE FROM unresolved_group_evidence WHERE kind IN ('prepared','comparison') AND external_key IN ('proposal:'||OLD.surface||':context','proposal:'||OLD.surface||':choice_context','proposal:'||OLD.surface||':album_choice_context'); DELETE FROM unresolved_group_contexts WHERE kind IN ('prepared','comparison') AND external_key IN ('proposal:'||OLD.surface||':context','proposal:'||OLD.surface||':choice_context','proposal:'||OLD.surface||':album_choice_context'); DELETE FROM group_evidence_owners WHERE kind IN ('prepared','comparison') AND external_key IN ('proposal:'||OLD.surface||':context','proposal:'||OLD.surface||':choice_context','proposal:'||OLD.surface||':album_choice_context'); END;
CREATE TABLE recommendation_policy_bodies (version TEXT PRIMARY KEY NOT NULL CHECK(length(version)>0),configuration_filename TEXT NOT NULL CHECK(length(configuration_filename)>0),content_digest TEXT NOT NULL CHECK(length(content_digest)=64 AND content_digest NOT GLOB '*[^0-9a-f]*'),byte_size INTEGER NOT NULL CHECK(typeof(byte_size)='integer' AND byte_size>0 AND byte_size<=8388608),configuration_offset INTEGER NOT NULL CHECK(typeof(configuration_offset)='integer' AND configuration_offset>=0),created_at REAL NOT NULL CHECK(typeof(created_at) IN ('real','integer') AND abs(created_at)<=1.7976931348623157e308),served INTEGER NOT NULL DEFAULT 0 CHECK(typeof(served)='integer' AND served IN (0,1))) WITHOUT ROWID;
CREATE INDEX ix_recommendation_policy_bodies_unused ON recommendation_policy_bodies(created_at,version) WHERE served=0;
CREATE TRIGGER recommendation_policy_bodies_immutable BEFORE UPDATE ON recommendation_policy_bodies WHEN NEW.version IS NOT OLD.version OR NEW.content_digest IS NOT OLD.content_digest OR NEW.byte_size IS NOT OLD.byte_size OR NEW.created_at IS NOT OLD.created_at BEGIN SELECT RAISE(ABORT,'Recommendation policy content is immutable'); END;
CREATE TABLE recommendation_policies (version TEXT PRIMARY KEY NOT NULL CHECK(length(version)>0),base_version TEXT REFERENCES recommendation_policy_bodies(version),configuration_filename TEXT NOT NULL CHECK(length(configuration_filename)>0),content_digest TEXT NOT NULL CHECK(length(content_digest)=64 AND content_digest NOT GLOB '*[^0-9a-f]*'),byte_size INTEGER NOT NULL CHECK(typeof(byte_size)='integer' AND byte_size>0 AND byte_size<=8388608),configuration_offset INTEGER NOT NULL CHECK(typeof(configuration_offset)='integer' AND configuration_offset>=0),created_at REAL NOT NULL CHECK(typeof(created_at) IN ('real','integer') AND abs(created_at)<=1.7976931348623157e308),served INTEGER NOT NULL DEFAULT 0 CHECK(typeof(served)='integer' AND served IN (0,1))) WITHOUT ROWID;
CREATE INDEX ix_recommendation_policies_unused ON recommendation_policies(created_at,version) WHERE served=0;
CREATE TRIGGER recommendation_policies_immutable BEFORE UPDATE ON recommendation_policies WHEN NEW.version IS NOT OLD.version OR NEW.base_version IS NOT OLD.base_version OR NEW.content_digest IS NOT OLD.content_digest OR NEW.byte_size IS NOT OLD.byte_size OR NEW.created_at IS NOT OLD.created_at BEGIN SELECT RAISE(ABORT,'Recommendation policy content is immutable'); END;
CREATE INDEX ix_recommendation_policy_base ON recommendation_policies(base_version,served,version);
CREATE INDEX ix_recommendation_policy_created ON recommendation_policies(created_at,version);
CREATE TABLE recommendation_impression_policies (impression_id INTEGER NOT NULL REFERENCES rec_served_impressions(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN ('primary','pool')),raw_version TEXT NOT NULL CHECK(typeof(raw_version)='text'),policy_version TEXT REFERENCES recommendation_policies(version),resolution_reason TEXT CHECK(resolution_reason IN ('missing_policy','invalid_type')),PRIMARY KEY(impression_id,kind),CHECK((policy_version IS NOT NULL AND policy_version=raw_version AND resolution_reason IS NULL) OR (policy_version IS NULL AND resolution_reason IS NOT NULL))) WITHOUT ROWID;
CREATE INDEX ix_recommendation_impression_policy ON recommendation_impression_policies(policy_version,impression_id,kind) WHERE policy_version IS NOT NULL;
CREATE INDEX ix_recommendation_unresolved_impression_policy ON recommendation_impression_policies(raw_version,impression_id,kind) WHERE resolution_reason='missing_policy';
CREATE TRIGGER recommendation_impression_evidence_insert BEFORE INSERT ON rec_served_impressions WHEN typeof(NEW.model_version)<>'text' OR CASE WHEN json_valid(NEW.provenance) THEN json_type(NEW.provenance)<>'object' ELSE 1 END BEGIN SELECT RAISE(ABORT,'Invalid served policy evidence'); END;
CREATE TRIGGER recommendation_impression_policy_capture AFTER INSERT ON rec_served_impressions BEGIN INSERT INTO recommendation_impression_policies(impression_id,kind,raw_version,policy_version,resolution_reason) SELECT s.impression_id,s.kind,s.raw_version,p.version,CASE WHEN s.valid=0 THEN 'invalid_type' WHEN p.version IS NULL THEN 'missing_policy' END FROM (SELECT i.id impression_id,'primary' kind,i.model_version raw_version,1 valid FROM rec_served_impressions i WHERE i.id=NEW.id UNION ALL SELECT i.id,'pool',CAST(json_extract(i.provenance,'$.pool_policy') AS TEXT),json_type(i.provenance,'$.pool_policy') IN ('text','integer') FROM rec_served_impressions i WHERE (i.id=NEW.id) AND json_type(i.provenance,'$.pool_policy') IS NOT NULL AND json_type(i.provenance,'$.pool_policy')<>'null') s LEFT JOIN recommendation_policies p ON s.valid=1 AND p.version=s.raw_version; END;
CREATE TRIGGER recommendation_impression_policy_immutable BEFORE UPDATE ON rec_served_impressions WHEN NEW.model_version IS NOT OLD.model_version OR NEW.provenance IS NOT OLD.provenance BEGIN SELECT RAISE(ABORT,'Served policy evidence is immutable'); END;
CREATE TRIGGER recommendation_impression_link_immutable BEFORE UPDATE ON recommendation_impression_policies WHEN NEW.impression_id IS NOT OLD.impression_id OR NEW.kind IS NOT OLD.kind OR NEW.raw_version IS NOT OLD.raw_version OR (OLD.policy_version IS NOT NULL AND NEW.policy_version IS NOT OLD.policy_version) BEGIN SELECT RAISE(ABORT,'Impression policy ownership is immutable'); END;
CREATE TRIGGER recommendation_impression_link_retained BEFORE DELETE ON recommendation_impression_policies WHEN EXISTS(SELECT 1 FROM rec_served_impressions WHERE id=OLD.impression_id) BEGIN SELECT RAISE(ABORT,'Retained impression requires its policy evidence'); END;
CREATE TRIGGER recommendation_impression_link_insert BEFORE INSERT ON recommendation_impression_policies WHEN NOT EXISTS(SELECT 1 FROM rec_served_impressions i WHERE i.id=NEW.impression_id AND ((NEW.kind='primary' AND NEW.raw_version=i.model_version AND NEW.resolution_reason IS NOT 'invalid_type') OR (NEW.kind='pool' AND NEW.raw_version=CAST(json_extract(i.provenance,'$.pool_policy') AS TEXT) AND CASE WHEN json_type(i.provenance,'$.pool_policy') IN ('text','integer') THEN NEW.resolution_reason IS NOT 'invalid_type' ELSE NEW.resolution_reason='invalid_type' END))) BEGIN SELECT RAISE(ABORT,'Policy reference does not match its impression'); END;
CREATE TRIGGER recommendation_impression_link_update BEFORE UPDATE ON recommendation_impression_policies WHEN NOT EXISTS(SELECT 1 FROM rec_served_impressions i WHERE i.id=NEW.impression_id AND ((NEW.kind='primary' AND NEW.raw_version=i.model_version AND NEW.resolution_reason IS NOT 'invalid_type') OR (NEW.kind='pool' AND NEW.raw_version=CAST(json_extract(i.provenance,'$.pool_policy') AS TEXT) AND CASE WHEN json_type(i.provenance,'$.pool_policy') IN ('text','integer') THEN NEW.resolution_reason IS NOT 'invalid_type' ELSE NEW.resolution_reason='invalid_type' END))) BEGIN SELECT RAISE(ABORT,'Policy reference does not match its impression'); END;
CREATE TRIGGER recommendation_impression_account_insert AFTER INSERT ON recommendation_impression_policies BEGIN UPDATE recommendation_policies SET served=EXISTS(SELECT 1 FROM recommendation_impression_policies WHERE policy_version=NEW.policy_version) WHERE version=NEW.policy_version; UPDATE recommendation_policy_bodies SET served=EXISTS(SELECT 1 FROM recommendation_policies WHERE base_version=recommendation_policy_bodies.version AND served=1) WHERE version=(SELECT base_version FROM recommendation_policies WHERE version=NEW.policy_version); END;
CREATE TRIGGER recommendation_impression_account_update AFTER UPDATE ON recommendation_impression_policies BEGIN UPDATE recommendation_policies SET served=EXISTS(SELECT 1 FROM recommendation_impression_policies WHERE policy_version=OLD.policy_version) WHERE version=OLD.policy_version; UPDATE recommendation_policy_bodies SET served=EXISTS(SELECT 1 FROM recommendation_policies WHERE base_version=recommendation_policy_bodies.version AND served=1) WHERE version=(SELECT base_version FROM recommendation_policies WHERE version=OLD.policy_version); UPDATE recommendation_policies SET served=EXISTS(SELECT 1 FROM recommendation_impression_policies WHERE policy_version=NEW.policy_version) WHERE version=NEW.policy_version; UPDATE recommendation_policy_bodies SET served=EXISTS(SELECT 1 FROM recommendation_policies WHERE base_version=recommendation_policy_bodies.version AND served=1) WHERE version=(SELECT base_version FROM recommendation_policies WHERE version=NEW.policy_version); END;
CREATE TRIGGER recommendation_impression_account_delete AFTER DELETE ON recommendation_impression_policies BEGIN UPDATE recommendation_policies SET served=EXISTS(SELECT 1 FROM recommendation_impression_policies WHERE policy_version=OLD.policy_version) WHERE version=OLD.policy_version; UPDATE recommendation_policy_bodies SET served=EXISTS(SELECT 1 FROM recommendation_policies WHERE base_version=recommendation_policy_bodies.version AND served=1) WHERE version=(SELECT base_version FROM recommendation_policies WHERE version=OLD.policy_version); END;
CREATE INDEX ix_album_reconciliation_canonical ON album_alias_reconciliations(album_id,retired_id);
CREATE TABLE album_description_requests (id INTEGER PRIMARY KEY AUTOINCREMENT,album_id INTEGER REFERENCES albums(id),request_key TEXT NOT NULL UNIQUE CHECK(length(request_key)>0),policy_version TEXT REFERENCES recommendation_policies(version),resolution_status TEXT NOT NULL CHECK(resolution_status IN ('resolved','legacy_unresolved')),legacy_identity TEXT UNIQUE,status TEXT NOT NULL CHECK(status IN ('pending','claimed','sent','uncertain','ready','unknown','invalid_response','auth','balance','rate_limit','unavailable','paused')),claim_token TEXT UNIQUE,lease_until REAL NOT NULL DEFAULT 0 CHECK(typeof(lease_until) IN ('real','integer') AND abs(lease_until)<=1.7976931348623157e308),attempt_count INTEGER CHECK(attempt_count IS NULL OR (typeof(attempt_count)='integer' AND attempt_count>=0)),credential_key TEXT,authorized_at REAL CHECK(authorized_at IS NULL OR (typeof(authorized_at) IN ('real','integer') AND abs(authorized_at)<=1.7976931348623157e308)),retry_at REAL NOT NULL DEFAULT 0 CHECK(typeof(retry_at) IN ('real','integer') AND abs(retry_at)<=1.7976931348623157e308),created_at REAL NOT NULL CHECK(typeof(created_at) IN ('real','integer') AND abs(created_at)<=1.7976931348623157e308),updated_at REAL NOT NULL CHECK(typeof(updated_at) IN ('real','integer') AND abs(updated_at)<=1.7976931348623157e308),outcome_filename TEXT,outcome_digest TEXT,outcome_format TEXT,CHECK((outcome_filename IS NULL AND outcome_digest IS NULL AND outcome_format IS NULL) OR (outcome_filename IS NOT NULL AND outcome_digest IS NOT NULL AND outcome_format IS NOT NULL AND length(outcome_filename)>0 AND outcome_format='album-description-1' AND length(outcome_digest)=64 AND outcome_digest NOT GLOB '*[^0-9a-f]*')),CHECK((resolution_status='resolved' AND album_id IS NOT NULL AND policy_version IS NOT NULL AND legacy_identity IS NULL AND attempt_count IS NOT NULL) OR (resolution_status='legacy_unresolved' AND album_id IS NULL AND policy_version IS NULL AND legacy_identity IS NOT NULL AND length(legacy_identity)>0 AND attempt_count IS NULL)),CHECK((status IN ('claimed','sent','uncertain') AND claim_token IS NOT NULL AND length(claim_token)>0 AND credential_key IS NOT NULL AND lease_until>=0) OR (status NOT IN ('claimed','sent','uncertain') AND claim_token IS NULL AND lease_until=0)),CHECK(status NOT IN ('sent','uncertain') OR authorized_at IS NOT NULL),UNIQUE(album_id,policy_version));
CREATE INDEX ix_album_description_album ON album_description_requests(album_id,policy_version,status);
CREATE INDEX ix_album_description_policy ON album_description_requests(policy_version,id) WHERE policy_version IS NOT NULL;
CREATE INDEX ix_album_description_active ON album_description_requests(lease_until,id) WHERE status IN ('claimed','sent');
CREATE UNIQUE INDEX ix_album_description_single_active ON album_description_requests((1)) WHERE status IN ('claimed','sent');
CREATE TABLE album_descriptions (id INTEGER PRIMARY KEY AUTOINCREMENT,request_id INTEGER NOT NULL UNIQUE REFERENCES album_description_requests(id),filename TEXT NOT NULL CHECK(length(filename)>0),format_version TEXT NOT NULL CHECK(format_version='album-description-1'),content_digest TEXT NOT NULL CHECK(length(content_digest)=64 AND content_digest NOT GLOB '*[^0-9a-f]*'),provider TEXT NOT NULL CHECK(provider='deepseek'),model_version TEXT NOT NULL CHECK(length(model_version)>0),created_at REAL NOT NULL CHECK(typeof(created_at) IN ('real','integer') AND abs(created_at)<=1.7976931348623157e308));
CREATE TRIGGER album_descriptions_immutable BEFORE UPDATE ON album_descriptions WHEN NEW.id IS NOT OLD.id OR NEW.request_id IS NOT OLD.request_id OR NEW.content_digest IS NOT OLD.content_digest OR NEW.format_version IS NOT OLD.format_version OR NEW.provider IS NOT OLD.provider OR NEW.model_version IS NOT OLD.model_version OR NEW.created_at IS NOT OLD.created_at BEGIN SELECT RAISE(ABORT,'Paid album description is immutable'); END;
CREATE TRIGGER album_descriptions_retained BEFORE DELETE ON album_descriptions BEGIN SELECT RAISE(ABORT,'Paid album descriptions have no cache expiry'); END;
CREATE TRIGGER album_description_owner_immutable BEFORE UPDATE ON album_description_requests WHEN NEW.id IS NOT OLD.id OR NEW.album_id IS NOT OLD.album_id OR NEW.request_key IS NOT OLD.request_key OR NEW.policy_version IS NOT OLD.policy_version OR NEW.legacy_identity IS NOT OLD.legacy_identity OR NEW.resolution_status IS NOT OLD.resolution_status OR NEW.created_at IS NOT OLD.created_at BEGIN SELECT RAISE(ABORT,'Album description request ownership is immutable'); END;
CREATE TRIGGER album_description_request_retained BEFORE DELETE ON album_description_requests BEGIN SELECT RAISE(ABORT,'Paid request evidence has no cache expiry'); END;
CREATE TRIGGER album_description_attempt_monotonic BEFORE UPDATE ON album_description_requests WHEN NEW.attempt_count<OLD.attempt_count BEGIN SELECT RAISE(ABORT,'Counted description attempts cannot be reset'); END;
CREATE TRIGGER album_description_success_retained BEFORE UPDATE ON album_description_requests WHEN OLD.status='ready' AND (NEW.status IS NOT OLD.status OR NEW.outcome_digest IS NOT OLD.outcome_digest) BEGIN SELECT RAISE(ABORT,'Successful album description cannot be replaced'); END;
CREATE TRIGGER album_description_success_insert BEFORE INSERT ON album_description_requests WHEN NEW.status='ready' AND NOT EXISTS(SELECT 1 FROM album_descriptions d WHERE d.request_id=NEW.id AND d.content_digest=NEW.outcome_digest) BEGIN SELECT RAISE(ABORT,'Successful request requires its durable result'); END;
CREATE TRIGGER album_description_success_update BEFORE UPDATE ON album_description_requests WHEN NEW.status='ready' AND NOT EXISTS(SELECT 1 FROM album_descriptions d WHERE d.request_id=NEW.id AND d.content_digest=NEW.outcome_digest) BEGIN SELECT RAISE(ABORT,'Successful request requires its durable result'); END;
CREATE TABLE legacy_album_description_usage (id INTEGER PRIMARY KEY AUTOINCREMENT,source_key TEXT NOT NULL UNIQUE CHECK(source_key='album_description_usage'),provider TEXT NOT NULL CHECK(provider='deepseek'),period INTEGER NOT NULL CHECK(typeof(period)='integer'),request_count INTEGER NOT NULL CHECK(typeof(request_count)='integer' AND request_count>=0),credential_key TEXT,status TEXT NOT NULL CHECK(status IN ('pending','claimed','sent','uncertain','ready','unknown','invalid_response','auth','balance','rate_limit','unavailable','paused')),claim_token TEXT,lease_until REAL NOT NULL CHECK(typeof(lease_until) IN ('real','integer') AND abs(lease_until)<=1.7976931348623157e308),send_authorized INTEGER NOT NULL CHECK(typeof(send_authorized)='integer' AND send_authorized IN (0,1)),retry_at REAL NOT NULL CHECK(typeof(retry_at) IN ('real','integer') AND abs(retry_at)<=1.7976931348623157e308),built_at REAL NOT NULL CHECK(typeof(built_at) IN ('real','integer') AND abs(built_at)<=1.7976931348623157e308),filename TEXT NOT NULL CHECK(length(filename)>0),content_digest TEXT NOT NULL CHECK(length(content_digest)=64 AND content_digest NOT GLOB '*[^0-9a-f]*'));
CREATE TRIGGER legacy_album_description_usage_immutable BEFORE UPDATE ON legacy_album_description_usage WHEN NEW.id IS NOT OLD.id OR NEW.source_key IS NOT OLD.source_key OR NEW.provider IS NOT OLD.provider OR NEW.period IS NOT OLD.period OR NEW.request_count IS NOT OLD.request_count OR NEW.credential_key IS NOT OLD.credential_key OR NEW.status IS NOT OLD.status OR NEW.claim_token IS NOT OLD.claim_token OR NEW.lease_until IS NOT OLD.lease_until OR NEW.send_authorized IS NOT OLD.send_authorized OR NEW.retry_at IS NOT OLD.retry_at OR NEW.built_at IS NOT OLD.built_at OR NEW.content_digest IS NOT OLD.content_digest BEGIN SELECT RAISE(ABORT,'Original paid usage evidence is immutable'); END;
CREATE TABLE provider_usage (id INTEGER PRIMARY KEY AUTOINCREMENT,request_id INTEGER REFERENCES album_description_requests(id),legacy_usage_id INTEGER REFERENCES legacy_album_description_usage(id),attempt_number INTEGER CHECK(attempt_number IS NULL OR (typeof(attempt_number)='integer' AND attempt_number>0)),reservation_key TEXT NOT NULL UNIQUE CHECK(length(reservation_key)>0),provider TEXT NOT NULL CHECK(provider='deepseek'),period INTEGER NOT NULL CHECK(typeof(period)='integer'),usage_kind TEXT NOT NULL CHECK(usage_kind IN ('requests','prompt_tokens','completion_tokens','total_tokens')),units INTEGER NOT NULL CHECK(typeof(units)='integer' AND units>=0),created_at REAL NOT NULL CHECK(typeof(created_at) IN ('real','integer') AND abs(created_at)<=1.7976931348623157e308),CHECK((request_id IS NOT NULL)+(legacy_usage_id IS NOT NULL)=1),CHECK(legacy_usage_id IS NULL OR attempt_number IS NULL),UNIQUE(request_id,attempt_number,usage_kind));
CREATE INDEX ix_provider_usage_period ON provider_usage(provider,period,usage_kind,units);
CREATE INDEX ix_provider_usage_request ON provider_usage(request_id,usage_kind);
CREATE UNIQUE INDEX ix_provider_usage_legacy_result ON provider_usage(request_id,usage_kind) WHERE request_id IS NOT NULL AND attempt_number IS NULL;
CREATE UNIQUE INDEX ix_provider_usage_legacy_count ON provider_usage(legacy_usage_id,usage_kind) WHERE legacy_usage_id IS NOT NULL;
CREATE TRIGGER provider_usage_attempt BEFORE INSERT ON provider_usage WHEN EXISTS(SELECT 1 FROM album_description_requests r WHERE r.id=NEW.request_id AND ((r.resolution_status='resolved' AND (NEW.attempt_number IS NULL OR NEW.attempt_number>r.attempt_count)) OR (r.resolution_status='legacy_unresolved' AND NEW.attempt_number IS NOT NULL))) BEGIN SELECT RAISE(ABORT,'Usage requires its actual request attempt'); END;
CREATE TRIGGER provider_usage_update BEFORE UPDATE ON provider_usage BEGIN SELECT RAISE(ABORT,'Metered provider usage is immutable'); END;
CREATE TRIGGER provider_usage_delete BEFORE DELETE ON provider_usage BEGIN SELECT RAISE(ABORT,'Metered provider usage is immutable'); END;
CREATE TABLE album_description_access (provider TEXT NOT NULL CHECK(provider='deepseek'),scope TEXT NOT NULL CHECK(scope IN ('host','credential')),credential_key TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('auth','balance','rate_limit','unavailable')),retry_at REAL NOT NULL CHECK(typeof(retry_at) IN ('real','integer') AND abs(retry_at)<=1.7976931348623157e308),updated_at REAL NOT NULL CHECK(typeof(updated_at) IN ('real','integer') AND abs(updated_at)<=1.7976931348623157e308),legacy_usage_id INTEGER REFERENCES legacy_album_description_usage(id),evidence_filename TEXT,evidence_digest TEXT,CHECK((evidence_filename IS NULL AND evidence_digest IS NULL) OR (evidence_filename IS NOT NULL AND length(evidence_filename)>0 AND evidence_digest IS NOT NULL AND length(evidence_digest)=64 AND evidence_digest NOT GLOB '*[^0-9a-f]*')),CHECK((scope='host' AND credential_key='' AND status='unavailable') OR (scope='credential' AND length(credential_key)>0 AND status IN ('auth','balance','rate_limit'))),PRIMARY KEY(provider,scope,credential_key)) WITHOUT ROWID;
CREATE TRIGGER prepared_recording_inputs_owner_insert BEFORE INSERT ON prepared_recording_inputs WHEN EXISTS(SELECT 1 FROM recording_redirects WHERE retired_id=NEW.recording_id) BEGIN SELECT RAISE(ABORT,'Prepared input owner is retired'); END;
CREATE TRIGGER prepared_recording_inputs_owner_update BEFORE UPDATE ON prepared_recording_inputs WHEN EXISTS(SELECT 1 FROM recording_redirects WHERE retired_id=NEW.recording_id) BEGIN SELECT RAISE(ABORT,'Prepared input owner is retired'); END;
CREATE TRIGGER retire_prepared_recording_inputs_insert AFTER INSERT ON recording_redirects BEGIN DELETE FROM prepared_recording_inputs WHERE recording_id=NEW.retired_id; END;
CREATE TRIGGER retire_prepared_recording_inputs_update AFTER UPDATE ON recording_redirects BEGIN DELETE FROM prepared_recording_inputs WHERE recording_id=NEW.retired_id; END;

